window.__T__=[{"i":10600,"text":"{\"type\":\"排版样本字帖\",\"style\":\"实验性异想天开的连笔字体设计，黑色单线循环字形，简洁极简的呈现方式\",\"canvas\":{\"orientation\":\"纵向\",\"background\":\"白色\",\"grid\":\"浅灰色细线表格，共 4 行 7 列，最后两个单元格留空\"},\"content\":{\"title\":\"自定义字母字体测试\",\"alphabet_count\":26,\"labels\":[\"A a\",\"B b\",\"C c\",\"D d\",\"E e\",\"F f\",\"G g\",\"H h\",\"I i\",\"J j\",\"K k\",\"L l\",\"M m\",\"N n\",\"O o\",\"P p\",\"Q q\",\"R r\",\"S s\",\"T t\",\"U u\",\"V v\",\"W w\",\"X x\",\"Y y\",\"Z z\"],\"empty_cells_count\":2},\"layout\":{\"cell_count\":28,\"filled_cells\":26,\"rows\":[{\"row\":1,\"count\":7,\"labels\":[\"A a\",\"B b\",\"C c\",\"D d\",\"E e\",\"F f\",\"G g\"]},{\"row\":2,\"count\":7,\"labels\":[\"H h\",\"I i\",\"J j\",\"K k\",\"L l\",\"M m\",\"N n\"]},{\"row\":3,\"count\":7,\"labels\":[\"O o\",\"P p\",\"Q q\",\"R r\",\"S s\",\"T t\",\"U u\"]},{\"row\":4,\"count\":5,\"labels\":[\"V v\",\"W w\",\"X x\",\"Y y\",\"Z z\"],\"empty_cells\":2}]},\"glyph_design\":{\"line_color\":\"{argument name=\\\"line color\\\" default=\\\"黑色\\\"}\",\"stroke\":\"粗细均匀、平滑圆润的单线，手绘矢量风格墨迹\",\"font_mood\":\"{argument name=\\\"font mood\\\" default=\\\"奇特俏皮的连笔风格\\\"}\",\"forms\":\"每个大写字母被重新设计为带有卷曲、结节、螺旋和夸张装饰笔触的大型装饰性连笔符号；小写字母仅作为标签中大写字母旁的小型印刷参考\",\"label_style\":\"每个单元格左上角的小号纯色无衬线黑色文本\"},\"composition\":\"在每个填充的单元格中心放置一个超大的装饰性字形，留出充足的留白并保持比例一致。保持字帖平整、正对视角、光照均匀，无阴影、无纹理、无透视变形。\",\"custom_text\":\"{argument name=\\\"alphabet labels\\\" default=\\\"A a, B b, C c, D d, E e, F f, G g, H h, I i, J j, K k, L l, M m, N n, O o, P p, Q q, R r, S s, T t, U u, V v, W w, X x, Y y, Z z\\\"}\"}","imgs":["https://r2.qqsrc.com/images/originals/18871.jpg"]},{"i":10601,"text":"{\"type\":\"字体样本图表\",\"subject\":\"一张完整的日语平假名五十音图，采用实验性的奇特循环线条字体渲染\",\"style\":{\"background\":\"干净的白纸\",\"grid\":\"纤细的浅灰色表格线\",\"ink\":\"纯黑色，平滑圆润的单线笔触\",\"letterform\":\"手绘草书字形，由夸张的圆环、结、漩涡和连续的记号笔笔触构成，风格俏皮但仍基于平假名\",\"composition\":\"平铺正面扫描视角，居中，极简，无阴影\"},\"layout\":{\"format\":\"纵向矩形图表\",\"columns\":{\"count\":5,\"headers\":[\"あ段\",\"い段\",\"う段\",\"え段\",\"お段\"]},\"rows\":{\"count\":11,\"labels\":[\"あ行\",\"か行\",\"さ行\",\"た行\",\"な行\",\"は行\",\"ま行\",\"や行\",\"ら行\",\"わ行\",\"ん\"]},\"cells\":{\"total visible glyphs\":46,\"description\":\"每个占用单元格内居中放置一个大型黑色自定义平假名字形；历史上的五十音空白单元格保持留白\",\"row contents\":[{\"row label\":\"あ行\",\"count\":5,\"glyphs\":[\"あ\",\"い\",\"う\",\"え\",\"お\"]},{\"row label\":\"か行\",\"count\":5,\"glyphs\":[\"か\",\"き\",\"く\",\"け\",\"こ\"]},{\"row label\":\"さ行\",\"count\":5,\"glyphs\":[\"さ\",\"し\",\"す\",\"せ\",\"そ\"]},{\"row label\":\"た行\",\"count\":5,\"glyphs\":[\"た\",\"ち\",\"つ\",\"て\",\"と\"]},{\"row label\":\"な行\",\"count\":5,\"glyphs\":[\"な\",\"に\",\"ぬ\",\"ね\",\"の\"]},{\"row label\":\"は行\",\"count\":5,\"glyphs\":[\"は\",\"ひ\",\"ふ\",\"へ\",\"ほ\"]},{\"row label\":\"ま行\",\"count\":5,\"glyphs\":[\"ま\",\"み\",\"む\",\"め\",\"も\"]},{\"row label\":\"や行\",\"count\":3,\"glyphs\":[\"や\",\"ゆ\",\"よ\"],\"blank columns\":[\"い段\",\"え段\"]},{\"row label\":\"ら行\",\"count\":5,\"glyphs\":[\"ら\",\"り\",\"る\",\"れ\",\"ろ\"]},{\"row label\":\"わ行\",\"count\":2,\"glyphs\":[\"わ\",\"を\"],\"blank columns\":[\"い段\",\"う段\",\"え段\"]},{\"row label\":\"ん\",\"count\":1,\"glyphs\":[\"ん\"],\"blank columns\":[\"い段\",\"う段\",\"え段\",\"お段\"]}]}},\"text\":{\"header font\":\"小型整洁的标准日语无衬线标签\",\"glyph font\":\"{argument name=\\\"实验性字体风格\\\" default=\\\"奇特的循环单线平假名\\\"}\",\"stroke color\":\"{argument name=\\\"笔触颜色\\\" default=\\\"黑色\\\"}\",\"grid color\":\"{argument name=\\\"网格颜色\\\" default=\\\"极浅灰色\\\"}\"},\"rendering instructions\":\"仅生成清晰的高分辨率表格图像。保持图表易于阅读且间距均匀，留出充足的边距，使用细网格边框，并确保每个自定义字形足够大，能够填满大部分单元格，同时保留手工循环书法的美感。\"}","imgs":["https://r2.qqsrc.com/images/originals/18872.jpg"]},{"i":10602,"text":"创作一张温馨且光影柔和的工作室肖像，三只可爱的毛绒质感幼崽并排坐在米色地板上，背景为平滑的米色：左侧是一只坐着的 {argument name=\"left animal\" default=\"幼年大熊猫\"}，拥有黑白相间的毛茸茸皮毛、圆耳朵和短粗的爪子，其面部被一个平坦的不透明棕褐色方形遮挡块刻意遮盖；中间是一只站立的小 {argument name=\"center animal\" default=\"幼年企鹅\"}，有着奶油色的蓬松腹部、深棕黑色的背部和头部、小巧的橙色喙和脚、亮黑色的眼睛，以及垂在身体两侧圆润的鳍状肢；右侧是一只坐姿端正的 {argument name=\"right animal\" default=\"浅米色小猫\"}，拥有圆圆的大眼睛、小耳朵、柔软的短毛、清晰可见的胡须和卷曲的尾巴。采用可爱的玩具风格 3D 渲染，呈现逼真的毛发纤维、柔和的轮廓光、浅景深、金色背光、地面上的柔和阴影、温馨的育婴室氛围、居中构图、高细节、电影般的暖色调，无文字。","imgs":["https://r2.qqsrc.com/images/originals/18875.jpg"]},{"i":10603,"text":"创作一张高分辨率的时尚编辑摄影作品，拍摄一名身材苗条的年轻女性站在宏伟历史豪宅的华丽室内楼梯上。她身穿一件宽松飘逸的 {argument name=\"dress color\" default=\"黑色\"} 挂脖迷你裙，领口有褶皱设计，侧面镂空，下摆短而不对称且带有飘逸感，并配有侧面系带细节，搭配简洁的 {argument name=\"shoe style\" default=\"白色低帮运动鞋\"}。她留着 {argument name=\"hair color\" default=\"深棕色\"} 的头发，随意地扎在脑后，脸部周围有几缕碎发，面部经过柔和的方形模糊处理以保持匿名。她优雅地站在灰色石阶上，双腿交叉，一只手搭在打磨光滑的弧形木质扶手上，采用低角度略微广角拍摄。场景特色包括雕刻精美的深色木质栏杆，上面装饰着圆形花卉镶板，高大的奶油色墙壁，左侧的大窗户投射出自然日光，右上角有一盏温暖的双灯泡壁灯，身后是蜿蜒的楼梯曲线。使用逼真的肤色、细腻的织物褶皱、光泽的雕刻木材、自然的室内光线、浅景深编辑效果、垂直构图以及高端生活方式杂志的风格。在左下方的楼梯附近添加一个微妙的半透明水印，文字为 {argument name=\"watermark text\" default=\"Alconia\"}。","imgs":["https://r2.qqsrc.com/images/originals/18876.jpg"]},{"i":10604,"text":"创作一张高度细节化的写实户外肖像，主角是一位 {argument name=\"subject description\" default=\"年轻东亚女性\"}，她跪在浅浅的岩石山溪中，呈四分之三侧面姿势，一只手撑在湿润的岩石上，另一只手臂自然下垂。她留着长长的深色头发，自然垂落在肩头并随风轻拂，面部被一个居中的方形像素化隐私遮挡块覆盖。她身穿一件修身的 {argument name=\"shirt color\" default=\"白色\"} 短袖 T 恤，左胸处印有黑色小巧的“CK”标志，下身穿着浅蓝色牛仔短裤；她赤着脚，膝盖和小腿浸在流动的溪水中。背景是郁郁葱葱的绿色森林山谷，布满光滑的大河石，溪水泛起白色的涟漪，远景是柔焦的林木山峦。采用自然阴天光线、冷色调、浅景深、逼真的皮肤纹理、湿润的岩石、电影级虚化效果、竖构图，呈现高分辨率 DSLR 摄影质感，具备 85mm 镜头感，柔和的对比度，并在左下角添加一个半透明的 {argument name=\"watermark text\" default=\"AIonia\"} 水印。","imgs":["https://r2.qqsrc.com/images/originals/18877.jpg"]},{"i":10605,"text":"创作一张高分辨率、写实的生活方式摄影作品，展示一名 {argument name=\"subject\" default=\"成年女性\"} 侧卧在深蓝色布艺沙发上，背景为明亮的客厅。她留着 {argument name=\"hair color and style\" default=\"深棕色长卷发\"}，发丝垂落在肩头，面部被一个位于头部及上脸部区域中央的大型不透明棕色遮挡方块刻意遮盖。她身穿浅灰色细肩带背心，胸前裹着一条柔软的 {argument name=\"blanket color\" default=\"蓝色抓绒毯\"}，一只手轻轻按在躯干附近的毯子上。构图为上半身和肩部的近景特写，略微俯拍，具有浅景深效果。背景为虚化的温馨家居内景，可见木质搁板、堆叠的书籍、藤编篮和一抹绿植，由自然光照亮。请使用 DSLR 级别的写实画质，呈现柔和的肤色、细腻的织物纹理、逼真的发丝，营造宁静放松的氛围，并在左下角添加一行半透明的 {argument name=\"watermark text\" default=\"Alconia\"} 水印。","imgs":["https://r2.qqsrc.com/images/originals/18878.jpg"]},{"i":10606,"text":"{\"type\":\"电影质感历史播客封面及纪录片缩略图\",\"aspect_ratio\":\"16:9 宽屏\",\"language\":\"中文可见排版\",\"style\":\"史诗级暗金历史纪录片设计，高级播客封面，照片级合成，中国古代宫廷剧与科学遗传学信息图表结合，高对比度明暗对照法，青蓝色与琥珀金调色，烟雾缭绕的氛围，细腻的羊皮纸纹理，雕刻地图线条，优雅的衬线体中文标题\",\"main_title\":\"{argument name=\\\"main title\\\" default=\\\"晋王的基因地图：李克用与沙陀之谜\\\"}\",\"subtitle\":\"{argument name=\\\"subtitle\\\" default=\\\"古 DNA 如何重绘晚唐沙陀的来源与混合历史\\\"}\",\"central_concept\":\"关于李克用与沙陀人的古 DNA 研究的宏大视觉呈现，结合唐代边疆政治、迁徙路线、墓葬考古及遗传祖源比例。\",\"layout\":{\"background\":\"分裂的历史景观：左半部分为冷色调东北草原，带有隐约的山脉、马队、地图网格线和发光的路线轨迹；右半部分为暖色调西部草原和废弃的堡垒景观，包含长城、烽火台、洞窟墓葬、石像和沙漠烟尘；地平线中央在两地交汇处发出光芒\",\"foreground_subject\":{\"position\":\"占据画面左侧约四分之一\",\"description\":\"一位强大的晚唐/晋王军阀，身着华丽的深色刺绣长袍、皮草披肩、珠宝腰带、礼仪发冠和金饰，呈四分之三侧身站立；面部被一个简单的矩形模糊块刻意遮挡\",\"side_name_plate\":\"{argument name=\\\"left name plate text\\\" default=\\\"李克用 晋沙陀领袖\\\"}\"},\"top_title\":{\"position\":\"中上方至右上角\",\"appearance\":\"非常巨大的浮雕金属质感金色中文字符，带有细腻阴影和风化纹理\",\"text\":\"{argument name=\\\"main title\\\" default=\\\"晋王的基因地图：李克用与沙陀之谜\\\"}\"},\"subtitle_band\":{\"position\":\"主标题下方\",\"appearance\":\"两侧带有细横分割线，较小的白金色中文字符\",\"text\":\"{argument name=\\\"subtitle\\\" default=\\\"古 DNA 如何重绘晚唐沙陀的来源与混合历史\\\"}\"},\"labeled_regions\":{\"count\":2,\"items\":[{\"position\":\"左中\",\"label\":\"东部草原\\n东北亚\",\"visual\":\"蓝色地图区域，带有发光的迁徙点和路线线\"},{\"position\":\"右中\",\"label\":\"西部草原\\n欧亚大陆腹地\",\"visual\":\"橙色地图区域，带有商队剪影和沙漠堡垒遗迹\"}]},\"genetics_infographic\":{\"position\":\"中下方\",\"description\":\"中央有一个发光的垂直 DNA 双螺旋结构，作为两条祖源流的汇合点；橙色和蓝色粒子云在其周围融合\",\"center_label\":\"汇合·融合\",\"charts\":{\"count\":2,\"items\":[{\"position\":\"中心左下方\",\"type\":\"蓝色环形图\",\"value\":\"53.4%\",\"label\":\"古代东北亚祖源\"},{\"position\":\"中心右下方\",\"type\":\"金色环形图\",\"value\":\"46.6%\",\"label\":\"西部草原祖源\"}]},\"bottom_statement\":{\"position\":\"底部中央，位于装饰性金边铭牌内\",\"text\":\"沙陀并非单一血缘共同体\"}},\"right_vertical_label\":{\"position\":\"右侧边缘，墓葬遗迹旁\",\"text\":\"{argument name=\\\"right vertical label text\\\" default=\\\"山西晋侯墓葬群\\\"}\"},\"decorative_science_elements\":{\"count\":5,\"items\":[\"右上角隐约的 DNA 螺旋图\",\"横跨天空的手写中文注释标记\",\"景观后方透明的科学图表网格\",\"穿过地图的细长发光迁徙路径\",\"底部中心附近的小型散点图式遗传数据点\"]},\"composition_notes\":\"保持所有文字清晰易读，在缩略图尺寸下平衡 YouTube/播客封面效果。使用电影级景深、真实光影、古代手稿细节、金色雕刻边框以及权威的历史悬疑基调。避免现代 UI 元素，避免卡通风格，避免主标题上方出现杂乱内容。\"}","imgs":["https://r2.qqsrc.com/images/originals/18879.jpg"]},{"i":10607,"text":"创作一张 16:9 的电影感播客封面插图，采用深色文艺复兴自然历史风格，融合复古油画与奇幻科学版画质感。左侧展示一位维多利亚时代的年长博物学家，外貌酷似查尔斯·达尔文，他坐在阴影中，身旁堆放着皮质书籍、一本画满植物与动物笔记的敞开素描本、散乱的纸张、黄铜仪器以及昏暗的书房墙壁；他的脸部被一个朴素的垂直棕色长方形色块遮挡，呈现出被涂抹的效果。画面中央及右侧展现出一片夕阳下的发光海景，远处的悬崖边有一艘帆船，空中飞鸟盘旋，一棵巨大的象征性生命之树枝干蜿蜒，铺满天空。在枝干间放置 13 个清晰可见的自然历史元素：一只美洲豹或豹子、一只猴子、一只熊类哺乳动物、一只栖息的鸟、两只在一起的小鸟、一只穿山甲类动物、一只狐狸或小型犬科动物、一只海龟、一只大型陆龟、一条鱼、一只蜥蜴或爬行动物、一个螺旋贝壳以及一个星状植物标本。右侧背景应过渡到深邃的宇宙蓝夜空，点缀着繁星、螺旋星系、圆形科学图表、化石、叶片、昆虫、根系和海洋生物，暗示进化、生物多样性与宇宙时间。运用戏剧性的明暗对比光影、温暖的金色高光、青绿色阴影、精细的雕刻细节、油画质感以及神秘的学术氛围。在画面下方中央放置醒目优雅的金色中文标题 {argument name=\"headline text\" default=\"大自然没有设计师\"}，下方配以较小的金色副标题 {argument name=\"subtitle text\" default=\"达尔文与生命之树\"}，两侧辅以纤细的装饰性分割线和小型花饰。保持排版清晰、居中、奢华且易读，呈现出高端科学历史播客封面的质感。整体色调：复古琥珀色、深森林绿、深青色、黑色与发光的金色；高细节，电影感构图，不包含任何现代物品。","imgs":["https://r2.qqsrc.com/images/originals/18880.jpg"]},{"i":10608,"text":"创作一张 16:9 横向比例的暗黑电影感播客封面，呈现出戏剧性的巴洛克油画质感，运用金棕色明暗对比照明、陈旧羊皮纸纹理，营造出历史悬疑氛围。画面右中前景处，一位疲惫的中世纪学者或磨坊主坐在粗糙的木桌前，面部被一块深色方形阴影刻意遮挡，一只手按在太阳穴上，另一只手正用羽毛笔在手稿上书写。桌上包含 5 个主要前景物品：一本画满图表的神秘笔记、散落的稿纸、一支燃烧的蜡烛、一块带孔的奶酪以及散落的幼虫；在奶酪和纸张周围精确包含 9 只清晰可见的幼虫。在他身后，将超现实的宇宙星空与星辰、占星圆环、布满陨石坑的月球、金色星云尘埃以及模糊的数学手稿符号融为一体，并过渡到左下方的中世纪晚期村庄和右上方的阴影中的教会官员或宗教裁判官。添加 4 个清晰可见的文本块：左侧是一个巨大的奶油色中文主标题 {argument name=\"main title\" default=\"奶酪宇宙里的磨坊主\"}，下方是一个较小的副标题 {argument name=\"subtitle\" default=\"《奶酪与蛆虫》与普通人的思想史\"}，左下角是一行极小的标语 {argument name=\"tagline\" default=\"— 当一个普通人开始解释宇宙，权力便开始不安。\"}，右侧是一张羊皮纸便签 {argument name=\"document note\" default=\"审讯记录\\n梅诺基奥\\n1599年\"}。使用优雅的繁体中文字体，标题采用灰白色墨迹，小标语采用暗金色，高对比度但边缘呈现风化效果，采用博物馆海报式构图，无现代物品，无干净的数字光泽，细节丰富，氛围阴郁且充满智性，适合作为历史哲学播客的单集封面。","imgs":["https://r2.qqsrc.com/images/originals/18881.jpg"]},{"i":10609,"text":"创作一张 16:9 的电影质感播客封面，采用深色中世纪哥特式皇家风格，类似于 HBO 历史纪录片海报。场景位于阴暗的教堂王座大厅内，配有黑色石拱门、两扇高耸的尖顶彩色玻璃窗、雕刻精美的哥特式建筑、烛光下的金色高光，以及深黑与抛光金色的配色方案。前景中央放置一位年迈国王的半身像，他身披厚重的毛皮斗篷，佩戴华丽的领饰，面朝前方；他的头部后方是一个错综复杂的超大金色王冠，形成类似光环的建筑图解，但用一个简单的垂直棕色矩形遮住面部，使其匿名化。在他身后融合精细的金色线条艺术，包括王冠、宏伟的教堂城市、皇家印章、带有类拉丁文的手稿羊皮纸以及拥挤的中世纪宫廷。左侧包含一面高大的纹章旗帜，上面绘有戴冠狮子纹章和王冠标志，左下角有四名坐着的朝臣，他们的面部被小棕色矩形遮挡。运用戏剧性的明暗对比法、烟雾质感、古旧羊皮纸纹理、精细的雕刻细节以及发光的金属金色字体。在底部居中添加三行文字：大号主标题 {argument name=\"main title\" default=\"王冠之下的不死之身\"}，在两条带有箭头装饰的细水平分割线之间添加较小的副标题 {argument name=\"subtitle\" default=\"从神学王权到现代国家的诞生\"}，以及一行带有装饰性花纹的小号作者/来源信息 {argument name=\"source line\" default=\"恩斯特·H.坎托洛维奇《国王的两个身体》\"}。布局需平衡且具有海报感，标题占据底部三分之一，王冠光环占据上方中心，画面中不得出现任何现代物品。","imgs":["https://r2.qqsrc.com/images/originals/18883.jpg"]},{"i":10610,"text":"{\"type\":\"宽屏营销提案 Slides，用于联名活动视觉概念\",\"format\":\"16:9 演示项目，简洁的商业演示文稿设计\",\"language\":\"中文可见文本，包含英文活动标题\",\"style\":\"可爱年轻化的品牌联名提案，淡粉色渐变背景，圆角白色卡片，柔和阴影，亮粉色标题，带有小型装饰性闪光和云朵，精致的代理商提案美学\",\"header\":{\"position\":\"顶部\",\"left_logos\":{\"count\":2,\"items\":[\"蜜雪冰城 logo，含雪王吉祥物及文字\",\"洛克王国 ROCO KINGDOM logo，含黑色皇冠图标\"],\"separator\":\"×\"},\"main_title\":\"{argument name=\\\"campaign title\\\" default=\\\"MIXUE × DI MO CAMPAIGN\\\"}\",\"large_chinese_headline\":\"{argument name=\\\"Chinese headline text\\\" default=\\\"甜蜜冒险 萌力出发\\\"}\",\"subtitle\":\"蜜雪冰城 × 洛克王国 迪莫联合活动\",\"right_hero\":\"大型蜜雪冰城奶茶杯，旁边是可爱的蓝白配色迪莫吉祥物，带有黄色角状耳朵和尾巴，漂浮在淡粉色彩虹条纹上\"},\"layout\":{\"main_sections_count\":3,\"sections\":[{\"title\":\"1. 项目简报\",\"position\":\"左侧卡片\",\"icon\":\"粉色剪贴板轮廓\",\"content_blocks_count\":3,\"content_blocks\":[{\"label\":\"项目背景：\",\"body\":\"蜜雪冰城与洛克王国人气角色‘迪莫’联名，以‘甜蜜冒险’为主题，打造限定产品、周边与沉浸式视觉体验，强化品牌年轻化心智，激发消费热情与社交传播。\"},{\"label\":\"项目时间：\",\"body\":\"2024 年 7 月（新品上市及联名周边同步上线）\"},{\"label\":\"合作亮点：\",\"bullets_count\":4,\"bullets\":[\"迪莫 IP 授权与专属形象定制\",\"联名饮品与限定包装、周边盲盒\",\"线下门店视觉焕新 & 户外大屏\",\"全渠道内容传播与用户互动\"]}],\"bottom_thumbnails\":{\"count\":4,\"items\":[\"街头门店海报样机\",\"带有迪莫和饮品的粉色活动立牌\",\"户外数字广告屏样机\",\"桌面收藏级周边与饮品展示\"]}},{\"title\":\"2. 核心创意\",\"position\":\"中央卡片\",\"icon\":\"粉色灯泡轮廓\",\"intro_headline\":\"以「甜蜜冒险」为主线，开启与迪莫的奇妙旅程！\",\"intro_body\":\"我们将迪莫设定为‘甜蜜冒险伙伴’，陪伴用户探索 MIXUE 的美味世界，传递快乐、元气与陪伴感。\",\"creative_cards_count\":4,\"creative_cards\":[{\"label\":\"核心角色：迪莫登场\",\"description\":\"萌力伙伴，元气出发\",\"icon_or_image\":\"迪莫吉祥物奔跑\"},{\"label\":\"核心体验：甜蜜冒险\",\"description\":\"联名新品 × 冒险主题视觉\",\"icon_or_image\":\"蜜雪冰城饮品杯\"},{\"label\":\"核心互动：一起出发\",\"description\":\"多触点互动，激发 UGC 与分享\",\"icon_or_image\":\"带有爱心的粉色聊天气泡\"},{\"label\":\"核心权益：限定收藏\",\"description\":\"联名周边与限定包装，提升收藏价值\",\"icon_or_image\":\"粉色礼盒\"}]},{\"title\":\"3. 目标与成果指标\",\"position\":\"右侧卡片\",\"icon\":\"粉色目标轮廓\",\"goals_block\":{\"label\":\"核心目标：\",\"bullets_count\":4,\"bullets\":[\"提升品牌年轻化形象与用户好感度\",\"推动新品销量增长\",\"扩大品牌声量与社交影响力\",\"沉淀用户资产，促进复购与会员增长\"]},\"kpi_tiles\":{\"title\":\"关键成果指标 (KPI)：\",\"count\":4,\"items\":[{\"label\":\"销售目标\",\"value\":\"+20%\",\"subtext\":\"联名新品销售额 vs 活动前同期\",\"icon\":\"粉色饮品杯\"},{\"label\":\"曝光目标\",\"value\":\"1 亿+\",\"subtext\":\"全渠道曝光总量\",\"icon\":\"粉色眼睛\"},{\"label\":\"互动目标\",\"value\":\"500 万+\",\"subtext\":\"互动总量（点赞/评论/分享等）\",\"icon\":\"粉色聊天表情\"},{\"label\":\"会员增长目标\",\"value\":\"30 万+\",\"subtext\":\"新增会员数\",\"icon\":\"粉色用户剪影\"}]},\"footnote\":\"数据目标为预估值，最终以实际执行效果为准；渠道覆盖：门店 / 线上商城 / 社交媒体 / OOH / KOL / 私域\"}]},\"visual_requirements\":{\"canvas\":\"{argument name=\\\"canvas size\\\" default=\\\"1152×768\\\"}\",\"palette\":\"{argument name=\\\"color palette\\\" default=\\\"柔和淡粉色、白色、亮粉色点缀、天蓝色吉祥物细节、小型黄色高光\\\"}\",\"typography\":\"粗体圆角无衬线中文字体标题，清晰易读的正文，符合专业品牌提案的层级结构\",\"composition\":\"三个等宽圆角白色面板水平排列在主标题下方，留白充裕，统一的粉色图标，精确的网格布局，高分辨率精致样机\"}}","imgs":["https://r2.qqsrc.com/images/originals/18884.jpg"]},{"i":10611,"text":"{\"type\":\"品牌联名活动项目与视觉提案板\",\"format\":\"宽屏 16:9 展示项目\",\"overall_style\":\"可爱商业风中国营销设计，淡粉色背景，圆角白色卡片，光泽感 3D 吉祥物渲染，梦幻甜点氛围，专业代理商提案布局\",\"collaboration\":{\"brand\":\"{argument name=\\\"drink brand\\\" default=\\\"MIXUE\\\"}\",\"partner\":\"{argument name=\\\"collaboration IP\\\" default=\\\"DI MO\\\"}\",\"campaign_title\":\"{argument name=\\\"campaign title\\\" default=\\\"MIXUE × DI MO CAMPAIGN MOODBOARD\\\"}\",\"chinese_event_name\":\"蜜雪冰城 × 洛克王国 迪莫联名活动\",\"hashtags\":[\"#甜蜜冒险\",\"#萌力出发\",\"#迪莫驾到\",\"#MIXUExDIMO\"]},\"main_visual\":{\"position\":\"顶部居中\",\"scene\":\"大型横向主视觉横幅，蓝色与白色 Q 版吉祥物在草莓珍珠奶茶和冰淇淋杯旁奔跑微笑，淡彩虹云朵，闪光点，冰淇淋山，可爱的奇幻冒险氛围\",\"headline\":\"{argument name=\\\"hero headline\\\" default=\\\"甜蜜冒险 萌力出发\\\"}\",\"supporting_badges\":[\"新品上市\",\"联名限定\"],\"colors\":\"棉花糖粉，天空蓝，奶油白，草莓红，柔和黄，薰衣草紫\"},\"mascot\":{\"description\":\"可爱的迪莫风格蓝色吉祥物，白色面部和腹部，大大的黑眼睛，脸颊有橙色小标记，额头有黄色 V 字标记，大大的蓝色耳朵配黄色耳尖，蓝色尾巴末端有星星，充满活力的奔跑姿势\",\"rendering\":\"高质量 3D 玩具质感角色与扁平化图形广告元素结合\"},\"layout\":{\"sections\":[{\"title\":\"MIXUE × DI MO CAMPAIGN MOODBOARD\",\"position\":\"左上\",\"count\":6,\"items\":[\"活动标题卡\",\"中文联名副标题\",\"话题标签行\",\"五个纯色色块\",\"一个多色淡彩纹理色块\",\"极简品牌字体\"]},{\"title\":\"数字横幅\",\"position\":\"左中\",\"count\":3,\"items\":[\"带有“甜蜜冒险 萌力出发”标题及吉祥物的横幅\",\"带有“迪莫联名套餐”及饮品、吉祥物和产品卡的横幅\",\"带有“新品上市 冒险开启”标题、吉祥物及柔和天空背景的横幅\"]},{\"title\":\"社交媒体横幅\",\"position\":\"右上\",\"count\":3,\"items\":[\"带有“甜蜜冒险 萌力出发”标题的竖版故事横幅\",\"带有“迪莫驾到”标题及吉祥物手持冰淇淋的竖版故事横幅\",\"带有“联名限定包装”标题及饮品包装的竖版故事横幅\"]},{\"title\":\"社交媒体贴文\",\"position\":\"右中\",\"count\":1,\"items\":[\"mixue_global 风格的 Instagram 正方形贴文样机，展示主视觉活动图、文案及互动图标\"]},{\"title\":\"印刷与户外广告\",\"position\":\"左下\",\"count\":3,\"items\":[\"公交站灯箱海报样机\",\"独立粉色竖版海报样机\",\"智能手机竖版广告样机\"]},{\"title\":\"美学视觉素材\",\"position\":\"下中\",\"count\":8,\"items\":[\"粉色爆爆珠\",\"粉色冰淇淋旋涡\",\"日落粉色云朵\",\"虹彩水晶纹理\",\"粉色闪光糖粒纹理\",\"棕色珍珠\",\"蓝色水波纹理\",\"淡彩闪光渐变\"]},{\"title\":\"周边与包装\",\"position\":\"右下\",\"count\":7,\"items\":[\"小型吉祥物钥匙扣\",\"大型品牌饮品杯\",\"淡彩角色饮品杯\",\"粉色联名包装盒\",\"扁平收藏卡或杯垫 1\",\"扁平收藏卡或杯垫 2\",\"印刷版活动插页\"]}],\"centerpiece\":\"写实的 MIXUE 门店样机，入口上方有大型活动广告牌，门前有顾客人群\",\"additional_photo_mockup\":\"手持户外联名珍珠奶茶杯的实拍图，杯身印有吉祥物和粉色顶料\"},\"bottom_branding\":{\"logos\":\"MIXUE logo × 洛克王国 logo\",\"position\":\"右下\"},\"design_requirements\":\"保持项目信息密度高但整洁，使用统一的圆角面板，写实的产品和户外广告样机，清晰易读的中文标题，专业活动提案质量，避免暗黑风格，避免杂乱的排版\"}","imgs":["https://r2.qqsrc.com/images/originals/18885.jpg"]},{"i":10612,"text":"{\"type\":\"电影感中文信息图海报，展示 AI 电影制作提示词工作流\",\"format\":\"竖版 3:4 海报\",\"overall_style\":\"深色高端电影制作控制室美学，黑色与深海军蓝背景，细腻的蓝图网格与技术 HUD 线条，暖金与冷青色点缀，高对比度，精致的排版布局，写实电影道具与简洁矢量图标结合，优雅的中文字体\",\"headline\":{\"position\":\"顶部居中\",\"text\":\"{argument name=\\\"main headline\\\" default=\\\"从制作团队角色出发：\\\\nGPT Image 2 × Seedance 2.0\\\\n全流程提示词方法论\\\"}\",\"style\":\"大号加粗白色衬线中文字体，配以金色强调，居中\"},\"subtitle\":{\"position\":\"标题下方\",\"text\":\"如果把提示词比作拍摄现场的对讲机，那么导演、制片、摄影师、音效老师，每一角色看到的画面、关心的参数、下达的指令都是完全不同的。\",\"style\":\"小号白色中文说明文字\"},\"top_props\":{\"count\":2,\"items\":[{\"description\":\"左上角导演椅，标注 DIRECTOR，灯光昏暗\"},{\"description\":\"右上角三脚架上的复古电影聚光灯，散发暖琥珀色光芒\"}]},\"main_comparison\":{\"position\":\"中上部\",\"count\":2,\"panels\":[{\"title\":\"GPT Image 2\",\"subtitle\":\"静态视觉设计\",\"position\":\"left\",\"accent_color\":\"青蓝色\",\"thumbnail_count\":4,\"thumbnails\":[\"暗色角色肖像定妆照\",\"风暴中电影感城市或战场环境\",\"分镜草图帧\",\"带有站立人物的电影感海报主视觉\"],\"bullet_count\":5,\"bullets\":[\"角色定妆照\",\"场景概念图\",\"分镜关键帧\",\"海报主视觉\",\"光线 / 构图 / 美术定调\"],\"button_label\":\"负责把画面做出来\",\"button_icon\":\"图像图标\"},{\"title\":\"Seedance 2.0\",\"subtitle\":\"动态视频生成\",\"position\":\"right\",\"accent_color\":\"暖金色\",\"thumbnail_count\":4,\"thumbnails\":[\"夜间追车或载具镜头，带播放图标\",\"暗色特写视频帧，带播放图标\",\"人物走过电影感走廊，带播放图标\",\"风暴景观动态镜头，带播放图标\"],\"bullet_count\":5,\"bullets\":[\"镜头运动\",\"人物动作\",\"微表情变化\",\"节奏与转场\",\"环境音 / 音乐氛围\"],\"button_label\":\"负责让画面动起来\",\"button_icon\":\"场记板播放图标\"}]},\"workflow_arrows\":{\"position\":\"对比面板之间\",\"count\":2,\"labels\":[\"协同工作：先定画面，再驱动画面\",\"从左至右蓝色箭头\",\"从右至左金色箭头\"]},\"production_team_grid\":{\"position\":\"中部\",\"count\":8,\"layout\":\"2 行 4 列\",\"cells\":[{\"number\":\"1\",\"title\":\"导演\",\"icon\":\"导演椅\",\"text\":\"定义戏剧目的、情绪转折、潜台词；决定观众应该感受到什么\"},{\"number\":\"2\",\"title\":\"制片\",\"icon\":\"剪贴板\",\"text\":\"控制场景复杂度、人物数量、执行成本；确保 AI 生成稳定、可落地\"},{\"number\":\"3\",\"title\":\"摄影师 / 摄影指导\",\"icon\":\"电影摄像机镜头\",\"text\":\"景别、机位、焦段、构图、景深；镜头语言服务人物心理\"},{\"number\":\"4\",\"title\":\"美术指导\",\"icon\":\"调色板与画笔\",\"text\":\"空间、道具、服装、色彩系统；让每个细节都在讲故事\"},{\"number\":\"5\",\"title\":\"灯光师\",\"icon\":\"摄影棚灯光\",\"text\":\"主光、辅光、轮廓光、色温、光比；用光影表达情绪\"},{\"number\":\"6\",\"title\":\"演员指导\",\"icon\":\"戏剧面具\",\"text\":\"表情、眼神、呼吸、手部动作；强调克制真实的表演细节\"},{\"number\":\"7\",\"title\":\"剪辑师\",\"icon\":\"胶片与剪刀\",\"text\":\"镜头起止状态、节奏、留白、转场；控制情绪推进\"},{\"number\":\"8\",\"title\":\"声音设计 / 音效老师\",\"icon\":\"音频波形\",\"text\":\"环境音、拟音、低频、音乐、沉默；让声音放大戏剧张力\"}]},\"pipeline_strip\":{\"position\":\"中下部\",\"count\":8,\"style\":\"青色线条图标通过箭头连接\",\"steps\":[\"剧本理解\",\"角色设定\",\"场景设计\",\"关键帧生成\",\"视频驱动\",\"声音氛围\",\"连续性控制\",\"成片输出\"]},\"prompt_formula_bar\":{\"position\":\"流水线下方\",\"title\":\"提示词写作公式\",\"count\":6,\"items\":[{\"icon\":\"对话气泡\",\"label\":\"这场戏讲什么？\"},{\"icon\":\"人物\",\"label\":\"人物想要什么？\"},{\"icon\":\"警告三角\",\"label\":\"人物害怕什么？\"},{\"icon\":\"相机\",\"label\":\"为什么这样拍？\"},{\"icon\":\"太阳与声波\",\"label\":\"光线和声音如何服务情绪？\"},{\"icon\":\"电影旗帜\",\"label\":\"最后一帧停在哪里？\"}]},\"core_principle_footer\":{\"position\":\"底部\",\"title\":\"核心原则：\",\"text\":\"{argument name=\\\"core principle text\\\" default=\\\"GPT Image 2 负责“定画面”，Seedance 2.0 负责“让画面动起来”\\\\n真正高级的提示词，不是堆砌形容词，而是像一个完整制作团队那样下达清晰、分工明确、可执行的创作指令。\\\"}\",\"decorations\":\"左侧大型指南针图标，右侧电影剧组与收音师剪影，暖色背光\"},\"color_palette\":{\"background\":\"近黑色海军蓝\",\"primary_text\":\"象牙白\",\"accent_1\":\"青蓝色\",\"accent_2\":\"金琥珀色\",\"lines\":\"纤细的金色与青色边框\"},\"composition_notes\":\"使用大量带有纤细发光边框的精确矩形模块，平衡间距，电影海报层级，清晰的中文文本，面向创作者的高端教程信息图，设计面板外无杂乱元素。\",\"customization\":{\"topic\":\"{argument name=\\\"topic\\\" default=\\\"AI 电影感提示词方法论\\\"}\",\"left tool name\":\"{argument name=\\\"left tool name\\\" default=\\\"GPT Image 2\\\"}\",\"right tool name\":\"{argument name=\\\"right tool name\\\" default=\\\"Seedance 2.0\\\"}\"}}","imgs":["https://r2.qqsrc.com/images/originals/18888.jpg"]},{"i":10613,"text":"{\"type\":\"高度详细的动漫角色参考表及官僚装备档案\",\"style\":\"简洁的技术插图、水彩与墨水动漫渲染、档案表格设计、细灰色绘图线、朱红色印章点缀、米白色纸张、密集但有序的注释、奇幻官僚美学\",\"document\":{\"title\":\"{argument name=\\\"sheet title\\\" default=\\\"01 检疫官\\\"}\",\"sheet_number\":\"01\",\"registry_code\":\"SMLC-01A\",\"record_number\":\"412-01-01\",\"issuing_agency\":\"通行与记录局，防卫事务与公共登记部\",\"mood\":\"官方海关与检疫人员档案，融合角色设计表\"},\"character\":{\"name_or_role\":\"{argument name=\\\"character role\\\" default=\\\"检疫官\\\"}\",\"centerpiece\":\"年轻女性检疫官全身正面像，站姿从容，表情略显羞涩，一只手靠近领带，另一只手拿着折叠的黑色检疫布架\",\"appearance\":{\"hair\":\"{argument name=\\\"hair color and style\\\" default=\\\"长长的深蓝黑色头发，配有柔和的刘海和及腰的自然卷\\\"}\",\"eyes\":\"大而柔和的蓝灰色眼睛\",\"face\":\"肤色苍白，表情温和，白色医用口罩遮住嘴部\",\"body\":\"纤细娇小的动漫比例\"},\"outfit\":{\"palette\":\"{argument name=\\\"main outfit palette\\\" default=\\\"白色、浅灰色、深青色、黑色皮革、黄铜五金件及红色印泥\\\"}\",\"pieces_count\":9,\"pieces\":[\"宽大的白色检疫长袍，覆盖着垂直的检查单和红色印章\",\"长袍下可见深青色内褶裙\",\"层叠的半透明悬挂面板，形似纸质表格\",\"结构化的灰色肩披和护袖\",\"黑色皮革多功能背带，带有扣环和袋子\",\"黑色手套\",\"超大号黑白相间带绑带的厚底凉鞋\",\"头戴式可折叠屋顶状检疫布架，带有悬挂标签\",\"带有小型检查标记的白色医用口罩\"]}},\"layout\":{\"format\":\"纵向技术档案页，带有装饰边框，中心角色占据页面主体，侧栏为带标签的装备图示和印章\",\"sections_count\":12,\"sections\":[{\"title\":\"左侧行政侧边栏\",\"position\":\"最左侧垂直条\",\"count\":7,\"labels\":[\"表号 01\",\"登记代码 SMLC-01A\",\"日期 萨尔明历 412 年 14 日\",\"圆形红色城市印章\",\"记录编号 412-01-01\",\"办公用网格\",\"授权机构：通行与记录局\"]},{\"title\":\"主标题\",\"position\":\"顶部中左\",\"count\":3,\"labels\":[\"01\",\"检疫官\",\"检疫通行授权\"]},{\"title\":\"授权标记\",\"position\":\"主人物左侧\",\"count\":3,\"labels\":[\"检疫授权印章（徽章）\",\"检查标签（示例）\",\"小型罗盘与星座图\"]},{\"title\":\"主角色正面视图\",\"position\":\"中心\",\"count\":1,\"labels\":[\"全身正面视图\"]},{\"title\":\"背面视图\",\"position\":\"左下\",\"count\":1,\"labels\":[\"全身背面视图，展示长发、背部背带、悬挂纸条、长袍面板和折叠架\"]},{\"title\":\"检疫布架（可折叠）\",\"position\":\"右上\",\"count\":2,\"labels\":[\"展开的伞状头架，带有悬挂标签\",\"折叠后的紧凑框架束\"]},{\"title\":\"便携式印章（消毒/封印）\",\"position\":\"右中上\",\"count\":4,\"labels\":[\"圆柱形印章装置\",\"小型长方形印章盒\",\"大型长方形便携印章盒\",\"圆形红色印章印记\"]},{\"title\":\"标签集/通行单（存储/未使用）\",\"position\":\"右中\",\"count\":10,\"labels\":[\"五张带有红色印章的狭长悬挂通行标签\",\"一张长条垂直通行单\",\"四张平整纸条或带有印章图示的折叠表格\"]},{\"title\":\"腰带/药瓶套件\",\"position\":\"右中下\",\"count\":3,\"labels\":[\"腰带安装的一排药瓶\",\"单个悬挂药瓶标签\",\"带有红十字的医疗风格长方形小袋\"]},{\"title\":\"审批分类卡\",\"position\":\"右下\",\"count\":2,\"labels\":[\"01 检疫官分类卡\",\"已批准通行红色印章\"]},{\"title\":\"底部页脚\",\"position\":\"底边\",\"count\":4,\"labels\":[\"官方印章框\",\"备注横线区域\",\"四个小型圆形审批印章\",\"检查/税务/记录/存档签名框\"]},{\"title\":\"装饰性技术图示\",\"position\":\"页面顶部及中部\",\"count\":2,\"labels\":[\"顶部附近的多边形网络图\",\"左中部附近的节点星座图\"]}]},\"equipment_detail\":{\"visible_accessories_count\":8,\"items\":[\"可折叠检疫头架\",\"多个垂直纸质符咒和通行标签\",\"便携式印章盒\",\"消毒印章圆柱\",\"腰带药瓶套件\",\"带有红十字的医疗小袋\",\"手中持有的黑色可折叠框架\",\"皮革带、扣环、夹子和黄铜紧固件\"]},\"text_and_marks\":{\"language_style\":\"混合使用英语官僚标签和装饰性东亚风格印章字符\",\"stamp_color\":\"{argument name=\\\"stamp color\\\" default=\\\"朱红色\\\"}\",\"instruction\":\"尽可能使用微小且清晰的英语标题，小标签使用装饰性的伪官方印章文字；保持页面平衡、精准，在参考表外观的基础上避免杂乱\"},\"composition\":\"中心人物应占据页面高度的三分之二左右；侧面图示为较小的正投影产品标注；使用淡淡的标尺线、方框、虚线分隔符和档案页边距；高分辨率，线条锐利，纸张质感细腻\"}","imgs":["https://r2.qqsrc.com/images/originals/18889.jpg"]},{"i":10614,"text":"{\"type\":\"信息密集的动漫奇幻参考图谱及世界观信息图\",\"language_and_text\":\"全文使用精致的日式印刷字体，但所有标签说明均使用英文。创建一张羊皮纸色的档案页面，配有细灰色边框、密集注释、箭头、物品标注及水墨渲染效果。\",\"main_title\":\"{argument name=\\\"main title\\\" default=\\\"塩霧の帳簿都市\\\"}\",\"subtitle\":\"一座盐湖账簿之城及检疫记录官僚机构，以详细的角色与场景设计图谱形式呈现。\",\"central_character\":{\"position\":\"居中，占据页面全高\",\"role\":\"{argument name=\\\"character role\\\" default=\\\"雾中检疫官\\\"}\",\"name\":\"{argument name=\\\"character name\\\" default=\\\"Kyoeki-kan in the Mist\\\"}\",\"appearance\":\"年轻动漫女性，齐肩蓝灰色短发，佩戴发带及小型装饰，面部刻意用柔和的矩形灰色模糊处理，无五官，姿态沉稳且具有学者气质\",\"clothing\":\"层叠的蓝灰色连帽斗篷，覆盖浅色几何边框图案，白色长袍及宽松白裤，配有腰带、小袋、文件标签、木质印章、红色印戳、绑带、防护袖套、护膝、绑腿及厚实的步行鞋\",\"held_objects\":\"左手持打开的账簿，右手持红色手柄的检查印章或盖章工具\",\"palette\":\"{argument name=\\\"color palette\\\" default=\\\"雾蓝色、奶油色羊皮纸、褪色的红色印章、深色墨水、暖棕色皮革\\\"}\",\"style\":\"精致的日式动漫概念艺术，融合历史类指南插画风格，水彩渲染，精准的线条，柔和的雾气，高细节\"},\"layout\":{\"page_orientation\":\"宽幅横向参考图谱\",\"overall_structure\":\"一个大型中心角色，周围环绕标注图解、城市景观、装备网格及流程插图\",\"sections\":[{\"title\":\"城市概览与概念文本\",\"position\":\"左上\",\"count\":3,\"items\":[\"大型标题块\",\"简短说明段落\",\"带有 5 条项目符号的世界观规则框\"]},{\"title\":\"代表性景观\",\"position\":\"中左\",\"count\":1,\"items\":[\"全景雾中运河港口，布满船只、灯笼、桥梁、塔楼及浮动检查标志\"]},{\"title\":\"水门与检查站\",\"position\":\"左下\",\"count\":1,\"items\":[\"正面视角的运河检查站，配有灯笼、码头、船只、检查员及编号标注\"]},{\"title\":\"船队构成\",\"position\":\"左下\",\"count\":6,\"items\":[\"官方检查船\",\"水门管理船\",\"检查船\",\"市场船\",\"维修船\",\"住宅船\"]},{\"title\":\"角色工具标注\",\"position\":\"角色右上方\",\"count\":5,\"items\":[\"小型木质检查印章\",\"红墨水瓶\",\"打开的登记账簿\",\"成捆的悬挂式货物标签\",\"透明检查布\"]},{\"title\":\"腰带与服饰标注\",\"position\":\"角色右侧\",\"count\":5,\"items\":[\"防水文件盒\",\"木箱状防护盒\",\"配有印章和小工具的腰带\",\"下摆覆盖物布料样本\",\"鞋类及鞋底细节样本\"]},{\"title\":\"城市全景\",\"position\":\"右上\",\"count\":1,\"items\":[\"大型雾气笼罩的盐湖浮动城市，拥有众多码头、运河、灯笼、船屋、塔楼、起重机及远处的堡垒剪影\"]},{\"title\":\"工具、材料与符号网格\",\"position\":\"右中\",\"count\":15,\"items\":[\"航运单据\",\"红色圆形通行印章\",\"标有 27 的蓝灰色水号标签\",\"检查学校铭牌\",\"货物标签\",\"红色封印标签\",\"折叠防水布\",\"盘绕的系泊绳\",\"白色盐水罐\",\"卷起的许可证腰带\",\"检查官印章工具\",\"两支检查用书写笔\",\"装满账簿的记录架\",\"木质干燥箱\",\"小型标签牌\"]},{\"title\":\"图解与图例\",\"position\":\"右下\",\"count\":6,\"items\":[\"包含 5 个小步骤的航道通行流程\",\"三种红色与紫色的印章类型\",\"货物标签读取方法\",\"检查布折叠与包裹方法\",\"绳结布料示例\",\"小型纸质标签示例\"]}]},\"environment_details\":\"港口场景应展现一座建立在码头和浮动平台上的雾气盐湖大都市，拥有数百艘小船、倒映在水中的红灯笼、宝塔式屋顶、官僚标志、编号标记及淡蓝色的晨雾。\",\"composition_rules\":\"保持图谱整洁易读：中心角色占据主导，左侧解释城市与船只，右侧解释装备与流程，使用精细的标注线连接对象。采用手工绘制的百科全书美学，而非现代 UI 风格。\",\"image_quality\":\"高分辨率概念艺术，清晰的微缩细节，柔和的水彩阴影，羊皮纸背景，平衡的页边距，非写实，无 3D 渲染\"}","imgs":["https://r2.qqsrc.com/images/originals/18890.jpg"]},{"i":10615,"text":"{\"type\":\"三联式评估对比海报\",\"language\":\"日语\",\"overall_style\":\"奶油色羊皮纸背景，优雅的编辑排版，面板周围有细深色边框，细腻的纸张纹理，居中的日语排版，标题下方带有小型装饰花纹的水平分隔线\",\"title_text\":\"{argument name=\\\"main title\\\" default=\\\"技量別リテイク比較\\\"}\",\"canvas\":\"横向 4:3 海报，温暖的米白色页边距，三个等宽的垂直图像面板水平排列\",\"shared_subject\":{\"description\":\"一位年轻的动漫风格少女，正面站立，身穿浅色无袖吊带裙，单手握着一根长长的黑色电缆，忧郁的科幻氛围\",\"hair\":\"{argument name=\\\"hair color\\\" default=\\\"短款红棕色波波头\\\"}\",\"dress\":\"{argument name=\\\"dress color\\\" default=\\\"浅粉米色\\\"}\",\"background_motif\":\"身后堆叠着高耸的旧 CRT 电视机和杂乱的电线\"},\"layout\":{\"section_count\":3,\"sections\":[{\"position\":\"left\",\"title\":\"自分の技量に準じたリテイク案\",\"subtitle\":\"現在の画力を反映した改善イメージ\",\"visual_style\":\"半精修动漫插画，带有绘画质感，柔和的黄昏光影，虽不完美但构图吸引人，黑暗混乱的塔状堆叠 CRT 显示器，部分屏幕发出桃色和淡紫色光芒，少女全身可见且面部细节清晰，解剖结构和布料渲染略显粗糙\"},{\"position\":\"center\",\"title\":\"初心者が描いたリテイク案\",\"subtitle\":\"シンプルな形取りと素朴な描写\",\"visual_style\":\"刻意呈现的业余铅笔和蜡笔草图，松散凌乱的线条，简化的块状 CRT 形状，平淡的浅色调，可见辅助线，稚嫩的比例，极简光影，面部区域留为模糊的方块，在保持相同构图的同时呈现儿童画般的粗糙感\"},{\"position\":\"right\",\"title\":\"商業プロレベルのリテイク案\",\"subtitle\":\"構図・光・質感まで洗練した完成形\",\"visual_style\":\"高度精修的商业动漫概念艺术，电影级逆光和戏剧性天空，复杂精细的 CRT 电视堡垒与电缆，发出蓝色和琥珀色光的逼真反射玻璃屏幕，丰富的氛围深度，精致的裙装布料质感与褶皱，面部区域被深色模糊方块遮挡，专业的色彩分级\"}]},\"typography\":\"顶部居中大号黑色明朝体日语标题，每个面板下方有较小的粗体日语标题，标题下方有微小的解释性副标题\",\"mood\":\"插画技能水平与 AI 辅助重绘建议的对比，怀旧赛博朋克忧郁感，艺术教育演示\",\"rendering_notes\":\"确保包含三个带边框的面板，三个标题块，每个面板中重复相同的少女与 CRT 电视构图，但以三种不同的技能水平渲染；无额外面板，无 Logo，无水印\"}","imgs":["https://r2.qqsrc.com/images/originals/18891.jpg"]},{"i":10616,"text":"创作一张写实的全身时尚人像，主角为 {argument name=\"subject\" default=\"一位年轻女性\"}，她正随意地倚靠在现代极简主义室内的一根大型浅色混凝土柱旁。她留着深棕色长波浪卷发，面部被柔和的矩形模糊效果刻意遮挡；她姿态放松，双肩靠墙，双手插在宽松的高腰阔腿蓝色牛仔裤前兜里。她身穿 {argument name=\"top\" default=\"一件纯白色短袖 T 恤\"}，赤着双脚，双腿微微交叉。场景设定为 {argument name=\"location\" default=\"一个带有深色抛光地面的现代混凝土楼梯间\"}，右侧设有宽阔的楼梯、棱角分明的混凝土栏杆，顶部附近有几何形状的窗格，柔和的自然光在地面和墙壁上投下长长的阴影。使用真实的比例、自然的肤色、细腻的织物褶皱、详尽的牛仔布纹理、浅景深、柔和的灰蓝色调、纪实编辑摄影风格、竖构图，比例为 4:5。在左下角添加一个半透明的白色水印，文字为 {argument name=\"watermark text\" default=\"Alconia\"}。","imgs":["https://r2.qqsrc.com/images/originals/18892.jpg"]},{"i":10617,"text":"创作一张逼真的竖构图肖像，主体为 {argument name=\"subject\" default=\"一位年轻女性\"}，坐在室内窗边，光线柔和，取景范围从上半身到头部。她留着浓密的长波浪 {argument name=\"hair color\" default=\"深棕色头发\"}，自然垂落在肩头，带有自然光泽和零星碎发。她穿着一件修身的罗纹针织 {argument name=\"sweater color\" default=\"深紫色\"} 高领毛衣，长袖设计，强调织物纹理、纵向罗纹和自然的褶皱感。她的双手在画面下方的腰部轻轻交叠。面部被一个位于中心的大型不透明方形马赛克刻意遮挡，色调为暖棕色，遮住了眼睛、鼻子和大部分面部特征，仅露出部分头发和一只耳朵。可见的手部皮肤纹理需真实细腻，采用浅景深效果，左侧柔和的窗光，背景为暖色调的中性米色室内环境，呈现自然阴影，具有高细节的单反相机摄影质感。在左下角添加一个淡淡的半透明水印，内容为 {argument name=\"watermark text\" default=\"AI conia\"}。","imgs":["https://r2.qqsrc.com/images/originals/18893.jpg"]},{"i":10618,"text":"创作一张照片级逼真的全身户外时尚人像，画面中一位 {argument name=\"subject age and gender\" default=\"成年年轻女性\"} 蹲在白色格子栅栏旁浅色的瓷砖人行道上。她留着长直的 {argument name=\"hair color\" default=\"深棕色头发\"}，发丝垂在肩头，面部经过柔和的方形马赛克模糊处理，双手托腮，手肘抵在膝盖上，呈现出害羞而沉思的姿态。她身穿一件修身的 {argument name=\"sweater color\" default=\"藏青色\"} 针织毛衣，袖口有罗纹设计，搭配一条短款 {argument name=\"skirt color\" default=\"米色\"} 短裙、黑色透明连裤袜以及黑色防水台高跟鞋。采用浅景深效果，背景柔和虚化，自然日光照明，色调柔和中性，呈现真实的皮肤和织物纹理，营造出抓拍的街头摄影感。构图采用 4:3 竖幅，主体位于画面中心偏左位置，右侧白色几何栅栏向背景延伸，左下角带有半透明的 {argument name=\"watermark text\" default=\"Alconia\"} 水印。","imgs":["https://r2.qqsrc.com/images/originals/18894.jpg"]},{"i":10619,"text":"{\"type\":\"可爱日系吉祥物角色设定集 / 原创角色设计图\",\"style\":\"柔和水彩与彩色铅笔插画，温暖的奶油色纸张背景，圆润可爱的造型，淡雅的甜瓜绿配色，手绘虚线边框，点缀小爱心、闪光和涂鸦，具有柔和的绘本质感\",\"character\":{\"name\":\"{argument name=\\\"character name\\\" default=\\\"もめもめメロン\\\"}\",\"concept\":\"来自温柔未来的软糯治愈系布丁状甜瓜，设计初衷是让人揉捏和拥抱\",\"main colors\":\"{argument name=\\\"main colors\\\" default=\\\"淡甜瓜绿、奶油色、蜂蜜黄、桃粉色\\\"}\",\"body\":\"圆滚滚的布丁状甜瓜身体，带有光泽感，顶部有白色哈密瓜网纹，小小的椭圆形脚，圆圆的脸颊状手臂，闭着双眼的睡颜，猫咪般的 w 型嘴，淡淡的粉色腮红\",\"top detail\":\"头顶有一个短小的绿色 T 字形甜瓜柄\",\"centerpiece\":{\"position\":\"左半部分\",\"scale\":\"非常大的全身吉祥物肖像，安静地坐着\",\"expression\":\"放松的睡颜微笑\",\"surrounding doodles\":\"对话气泡写着 もめ〜，桃心，绿色装饰线，闪光，以及一个小甜瓜切片，配文 メロンの香りつき〜\"}},\"layout\":{\"title\":{\"position\":\"顶部中右侧\",\"text\":\"{argument name=\\\"title text\\\" default=\\\"もめもめメロン\\\"}\",\"lettering\":\"大号圆润的绿色日文艺术字，带白色描边和柔和阴影，装饰有一个小甜瓜图标\"},\"subtitle\":{\"position\":\"标题下方的丝带横幅\",\"text\":\"揉むと癒やされる、プリン型メロンのゆる未来キャラ。\",\"style\":\"棕色手写体，位于淡奶油色丝带上，两端为绿色\"},\"sections\":[{\"title\":\"プロフィール\",\"position\":\"左下\",\"count\":1,\"content\":\"ゆるい未来からやってきた、ぷるぷるのメロンプリン。あなたががんばりすぎた時、そっと寄りそってくれるよ。いっしょに、ゆるゆる もめもめしよ〜♪\",\"visuals\":\"云朵状虚线边框，左侧有小甜瓜图标，右下角有小爱心\"},{\"title\":\"いろんな もめもめ♪\",\"position\":\"中间列\",\"count\":3,\"labels\":[\"むにっ\", \"ぷるぷる\", \"Zzz…\"],\"items\":[\"顶部小图：人手轻轻按压柔软的甜瓜吉祥物，脸颊向内凹陷，对话气泡 むにっ\",\"中间小图：吉祥物快乐地颤动，带有动态线，对话气泡 ぷるぷる\",\"底部小图：吉祥物躺在薰衣草色垫子的阴影上睡觉，对话气泡 Zzz…\"]},{\"title\":\"traits panel\",\"position\":\"右侧\",\"count\":4,\"labels\":[\"性格\", \"特技\", \"弱点\", \"口ぐせ\"],\"items\":[\"爱心图标行：性格：のんびり / やさしい / すぐ寝る\",\"闪光图标行：特技：手のひらの疲れを吸い取る / ぷるぷる振動 / 癒やし\",\"太阳图标行：弱点：暑さ / スプーン / 高級フルーツ売り場\",\"对话气泡图标行：口ぐせ：『もめ〜』\"]},{\"title\":\"おすすめの楽しみ方\",\"position\":\"右下\",\"count\":4,\"labels\":[\"手のひらにのせて…\", \"やさしくもみもみ…\", \"疲れがとけるよ〜\", \"いっしょにすやすや…ZZZ\"],\"items\":[\"小吉祥物放在手心里，配有小爱心\",\"双手轻轻揉捏吉祥物脸颊\",\"大爱心图标，表示治愈\",\"吉祥物睡觉，带有蓝色小气泡\"]}]},\"composition\":\"16:9 宽幅角色设定集，主吉祥物占据左半部分，信息面板整齐排列在中间和右侧，统一的圆润虚线框，所有文字均为日文手写体，无生硬阴影，留有充足的呼吸空间\",\"mood\":\"{argument name=\\\"mood\\\" default=\\\"sleepy, comforting, playful, healing\\\"}\",\"rendering notes\":\"使吉祥物看起来极其柔软、半透明且像布丁一样，带有细腻的黄绿色渐变、湿润的光泽感、顶部精致的哈密瓜网纹，整体呈现出手工文具的质感\"}","imgs":["https://r2.qqsrc.com/images/originals/18895.jpg"]},{"i":10620,"text":"{\"type\":\"高能量动漫角色设计图，虚构的不良少女英雄\",\"format\":\"16:9 宽屏海报，杂志角色设定集，日式街头朋克漫画美学\",\"overall_style\":\"爆炸性的黑、亮粉、红、奶油色与金色配色；粗犷的墨迹飞溅、速度线、贴纸式图标、网点纹理、锯齿状漫画字体、光泽赛璐珞阴影、戏剧性的霓虹高光、混乱但清晰的布局\",\"character\":{\"name\":\"{argument name=\\\"character name\\\" default=\\\"バトル鬼ヶ島ちゃんのゲヒー\\\"}\",\"concept\":\"来自银河帮的转校生，深色皮肤的鬼族不良高中女生，叛逆但讲义气，大嗓门且充满活力\",\"appearance\":\"红褐色皮肤，鲜艳的洋红色发光双眼，尖锐的獠牙，顽皮的坏笑，两只光泽红色的鬼角，极长的凌乱黑发中夹杂着如星系般流动的紫色与粉色光带，佩戴星星发夹及小型朋克饰品\",\"outfit\":\"金色缎面横须贺夹克，黑色袖子，红色内衬，饰有鬼族补丁、汉字补丁、骷髅及帮派徽章；白色校服衬衫搭配松开的红色领结；黑色腰带与链条配饰；红黑格纹百褶裙；大腿绷带与腿部创可贴；厚底黑红配色高帮运动鞋\",\"weapon\":\"金属棒球棍，覆盖着贴纸、汉字标记、铆钉、划痕以及粉黑色高光\",\"main_pose\":\"全身像位于左侧，以傲慢的宽站姿站立，一手叉腰，装饰过的球棍扛在肩上，直视观众，露出自信且带有獠牙的坏笑\"},\"layout\":{\"background\":\"灰白色做旧纸张底色，布满粉色笔触、黑色墨水爆炸、星星、骷髅、爱心、行星、涂鸦标记及对角线运动划痕\",\"sections\":[{\"title\":\"大型标题字体\",\"position\":\"顶部居中\",\"count\":1,\"text\":\"{argument name=\\\"headline text\\\" default=\\\"バトル 鬼ヶ島ちゃんのゲヒー\\\"}\",\"style\":\"巨大的手绘日式漫画字体，黑色与亮粉色搭配，带有飞溅装饰\"},{\"title\":\"标语块\",\"position\":\"标题下方居中\",\"count\":1,\"text\":\"{argument name=\\\"tagline text\\\" default=\\\"銀河団から転校してきた、赤肌鬼ヤンキーJK。\\\"}\",\"style\":\"黑色笔触矩形框，内含白色与粉色日文文本\"},{\"title\":\"个人档案备注\",\"position\":\"中间居中\",\"count\":4,\"labels\":[\"性格：义气深重 / 嘴硬心软 / 重视伙伴\",\"特技：陨石本垒打 / 咆哮黑洞 / 炒面面包争夺战\",\"弱点：甜食 / 夸奖 / 恋爱话题\",\"口头禅：『嘿嘿，揍飞你哦』\"],\"style\":\"四行横向带横线的档案行，配有小型粉黑图标：星星、火焰球、破碎的心、对话气泡\"},{\"title\":\"帮派徽章\",\"position\":\"左下角\",\"count\":1,\"description\":\"圆形黑金徽章，绘有愤怒的鬼脸及文字『银河团』，外加手写标语『地球的常识，对我可不管用!!』\"},{\"title\":\"右侧漫画分镜\",\"position\":\"右侧栏\",\"count\":3,\"panels\":[\"顶部特写：鬼族少女向前倾身，双眼发光，獠牙与鬼角显露，星系长发飘动，背景有星星，对话气泡写着『嘿嘿，揍飞你哦』\", \"中间动作分镜：她挥动棒球棍击中宇宙爆炸中的燃烧陨石，巨大的拟声词文字『陨石本垒打!!』\", \"底部可爱弱点分镜：被甜点、爱心、甜甜圈、芭菲、蛋糕包围，对话气泡写着『唔……甜食可是犯规的啊……』；包含一个如样本布局中所示的小型遮盖/涂抹面部区域\"]}],\"small_decorations\":{\"count\":7,\"items\":[\"最左侧大型黑色鬼字\",\"粉色星星贴纸\",\"黑色骷髅图标\",\"火焰骷髅贴纸\",\"紫色带环行星贴纸\",\"小爱心\",\"黑色笔触飞溅斑点\"]}},\"typography\":\"混合粗体毛笔书法日文、手写注释文本、漫画拟声词、贴纸标签及粗犷下划线；严格保留所有指定位置的日文文本\",\"rendering\":\"清晰细腻的动漫插画，饱和的霓虹高光，厚重的黑色线条，光泽织物反射，动态构图，专业的角色设定集呈现，非写实风格\"}","imgs":["https://r2.qqsrc.com/images/originals/18897.jpg"]},{"i":10621,"text":"{\"type\":\"日式吉祥物角色设定集 / 比赛参赛海报\",\"format\":\"宽幅横向信息图角色设计表，16:9，干净的奶油色背景，配有橙色装饰边框、神社元素、闪光和放射线，高细节可爱动漫吉祥物插画，温暖的橙色与金色调，清晰的矢量风格线条与水彩阴影\",\"main_title\":{\"position\":\"左上角\",\"text\":\"{argument name=\\\"character name\\\" default=\\\"电子微波炉大明神 チンノスケ\\\"}\",\"style\":\"大型粗体日文展示字体，上方带有黑色振假名，超大橙色书法字体名称\"},\"tagline\":{\"position\":\"标题下方\",\"text\":\"{argument name=\\\"tagline\\\" default=\\\"来自加热过度的未来，为你加热的神明。\\\"}\",\"style\":\"橙色边框丝带标签\"},\"character\":{\"centerpiece\":\"全身正面原创神明吉祥物，一个可爱的小神明，头部是一个白色的微波炉，屏幕脸部发出橙色光芒，圆脸，粗眉毛，小胡子，微笑表情，右侧有微波炉按钮和 600w 标签，黑色电源插头线从头部延伸出来，身穿华丽的白、橙、黑、金配色神职人员礼服，肩上系着粗大的注连绳，配有纸垂、流苏、图案和服层叠，脚穿木屐，手持顶部带有发光饭碗符号的仪式权杖\",\"head_details\":\"头部上方安装有类似鸟居的金色光环和五块木制祈祷牌，分别标注：解冻、加热、加热神、自动、强弱\",\"body_details\":\"前围裙面板标注 600w 及蒸汽饭碗标志，袖子上挂着符咒和小标签\",\"expression\":\"微波炉窗口内显示出神明开朗的吉祥物面孔\"},\"layout\":{\"sections\":[{\"title\":\"特征档案框\",\"position\":\"左中\",\"count\":4,\"labels\":[\"性格：爱操心 / 温柔 / 不擅长控制火候\",\"特技：瞬间加热冷饭 / 测量心灵温度\",\"弱点：铝箔纸 / 停电 / 怕烫\",\"口头禅：『600 瓦的慈悲』\"],\"style\":\"带有橙色图标的圆角白色卡片：花朵、饭碗、警告三角形、对话气泡\"},{\"title\":\"功效\",\"position\":\"左下\",\"count\":3,\"labels\":[\"冷饭变得热腾腾！\",\"疲惫的心灵被温暖！\",\"对自己未来的生活更温柔！\"],\"style\":\"带有蝴蝶结装饰的木制神社看板，外加一只抱着写有“温暖未来”牌子的招财猫\"},{\"title\":\"全力加热姿势！\",\"position\":\"右上\",\"count\":1,\"labels\":[\"即使加热过度，只要有爱就没问题！\"],\"style\":\"带有橙色速度线的动作姿势面板，吉祥物戏剧性地指向天空，微波炉脸部表情凶猛\"},{\"title\":\"细节介绍\",\"position\":\"右中\",\"count\":3,\"labels\":[\"头部的御札（操作札）\",\"注连绳电源线\",\"腹部的操作面板\"],\"style\":\"三个圆形细节标注，配有简短说明文字，展示木制控制牌、编织绳电源插头和 600w 腹部控制面板\"},{\"title\":\"弱点瞬间……\",\"position\":\"右下\",\"count\":3,\"labels\":[\"铝箔纸连神明都能反射……！\",\"停电时就成了普通的箱子神……！\",\"因为怕烫所以热食很难受……\"],\"style\":\"三个小型圆角面板，展示滑稽的弱点场景：铝箔纸反光、黑暗停电、因食物太烫而流泪\"}],\"total_discrete_sections\":5,\"decorative_elements\":\"橙色边角装饰、小云朵、闪光、放射状太阳光线、标题上方的神社图标、猫咪附近的小印章式签名\"},\"typography\":\"所有可见文字均为日文，俏皮的漫画风格标题，配有橙色强调，整洁的黑色正文说明，汉字上方偶尔带有振假名\",\"rendering_instructions\":\"使其看起来像是一张精致的日式角色设定集，用于未来角色发现节，构图平衡，大吉祥物居中，无写实感，无 3D，标签高度可读，可爱的幽默基调，海报布局紧凑但井然有序\",\"customization\":{\"core_concept\":\"{argument name=\\\"mascot concept\\\" default=\\\"一位既能加热食物也能温暖人心的微波炉神明\\\"}\",\"catchphrase\":\"{argument name=\\\"catchphrase\\\" default=\\\"『600 瓦的慈悲』\\\"}\",\"color_palette\":\"{argument name=\\\"color palette\\\" default=\\\"暖橙色、金色、奶油色、白色和黑色\\\"}\"}}","imgs":["https://r2.qqsrc.com/images/originals/18898.jpg"]},{"i":10622,"text":"{\"type\":\"可爱的日本吉祥物角色设定集 / 比赛参赛卡\",\"style\":\"明亮的动漫插画，精致的游戏角色概念艺术，Q 版吉祥物设计，奶油色羊皮纸背景配青色装饰边框，青色发光数字特效，水彩云朵与传统日本元素融合未来感 UI 图标\",\"main_title\":\"{argument name=\\\"headline text\\\" default=\\\"Wi-Fi 狸猫 Pon-suke 5G\\\"}\",\"subtitle\":\"用电波幻化，未来型狸猫妖怪。\",\"character\":{\"name\":\"{argument name=\\\"character name\\\" default=\\\"Pon-suke\\\"}\",\"species\":\"未来风狸猫妖怪吉祥物\",\"body\":\"圆润饱满的棕色狸猫，带有奶油色肚皮，条纹蓬松尾巴，小耳朵，肉垫，开心的张嘴笑容\",\"eyes\":\"巨大的黑色圆形赛博眼睛，闪烁着青色的 Wi-Fi 符号\",\"accessories\":\"带有发光电路纹路和小型天线的绿叶帽，蓝色项圈绳，标有 5G 的木牌，肚皮上闪烁着青色 Wi-Fi 符号，尾巴上安装着天线装置\",\"pose\":\"全身中心位，挥动一只爪子，站在圆形的蓝色全息数字平台上，周围有像素方块和信号环\"},\"layout\":{\"format\":\"宽幅横向角色参考图，16:9，信息密集但充满趣味\",\"centerpiece\":\"中心位置是一幅巨大的狸猫吉祥物全身肖像，周围环绕着蓝色无线电波弧线和数字粒子\",\"left_profile_panel\":{\"position\":\"左侧\",\"count\":4,\"items\":[{\"icon\":\"绿叶脸部图标\",\"label\":\"性格：\",\"text\":\"随和 / 热心 / 爱恶作剧\"},{\"icon\":\"蓝色 Wi-Fi 图标\",\"label\":\"技能：\",\"text\":\"随时随地 Wi-Fi / 电波分身 / 妖怪智能家电化\"},{\"icon\":\"紫色微波炉或家电图标\",\"label\":\"弱点：\",\"text\":\"微波炉 / 忘记密码 / 深山老林\"},{\"icon\":\"橙色对话气泡图标\",\"label\":\"口头禅：\",\"text\":\"{argument name=\\\"catchphrase\\\" default=\\\"『Pon，连接完成』\\\"}\"}]},\"right_showcase_panels\":{\"position\":\"右侧堆叠面板\",\"count\":3,\"panels\":[{\"description\":\"顶部面板：狸猫在周围制造出多个半透明的蓝色无线电波分身，带有垂直侧标签\",\"visible_label\":\"电波分身之术！\"},{\"description\":\"中间面板：狸猫拿着智能手机眨眼，周围环绕着智能家电，包括微笑的冰箱、扫地机器人、智能音箱和灯泡创意图标，带有垂直侧标签\",\"visible_label\":\"妖怪智能家电化！\"},{\"description\":\"底部面板：狸猫躲在带有绿色花纹的毯子下显得很担心，头顶有一小团沮丧的卷曲符号，带有垂直侧标签\",\"visible_label\":\"不太擅长深山老林……\"}]},\"bottom_left_scenery\":\"小型蓝色剪影景观，包含鸟居、松树、山峦、云朵，以及一个举着 Wi-Fi 信号的小狸猫身影\"},\"color_palette\":\"温暖的狸猫棕色与奶油色，深海军蓝轮廓，鲜艳的青色与电光蓝发光效果，青绿色叶子点缀，羊皮纸米色背景\",\"rendering_details\":\"清晰的粗轮廓线，柔和的赛璐珞阴影，光泽发光效果，装饰性边角，日本节日海报风格，易读的手写风格日语排版，非写实风格\"}","imgs":["https://r2.qqsrc.com/images/originals/18899.jpg"]},{"i":10623,"text":"{\"type\":\"realistic smartphone camera-roll collage\",\"style\":\"超写实休闲日本社交媒体快照拼贴，真实的 iPhone 照片，混合室内外光线，轻微运动模糊，浅景深，自然肤色，每张脸部均有保护隐私的模糊方块，无美颜修图\",\"main_subject\":{\"description\":\"一位留着齐肩深棕色头发的年轻女性，身材苗条，穿着一件简单的白色 T 恤，胸前印有可爱的站立水獭插画\",\"identity\":\"{argument name=\\\"subject description\\\" default=\\\"留着齐肩深棕色头发的年轻日本女性\\\"}\",\"outfit\":\"{argument name=\\\"outfit\\\" default=\\\"印有可爱站立水獭图案的白色 T 恤\\\"}\",\"face_treatment\":\"每张照片中覆盖脸部的大型柔和像素化模糊方块\"},\"layout\":{\"format\":\"单张 1:1 正方形图像，类似相册导出，照片边缘重叠，无白边，随意的非规则网格，部分照片经过裁剪，中心图像部分遮盖周围图像\",\"photo_count\":9,\"photos\":[{\"position\":\"top left\",\"description\":\"女性颈部、下颌线、头发和白色 T 恤的极近距离自拍裁剪；温暖的室内光；左侧边缘有手指或手部闯入\"},{\"position\":\"top center\",\"description\":\"凌乱的卧室或公寓镜子自拍，女性穿着白色水獭 T 恤坐着，一只手伸向镜头产生运动模糊，背景中有电脑显示器和家居用品\"},{\"position\":\"top right\",\"description\":\"高角度户外行走自拍，女性穿着白色 T 恤沿着垃圾桶和建筑墙壁旁的小巷移动，头发被风吹起，有运动模糊\"},{\"position\":\"middle left\",\"description\":\"餐厅餐桌抓拍，女性穿着水獭 T 恤坐着，面前有意大利面，带吸管的冰饮，身后是繁忙的休闲餐厅，可见水印\"},{\"position\":\"center large\",\"description\":\"覆盖在拼贴画上的主导垂直中心照片，被一个大的不透明模糊矩形严重遮挡，呈现出隐私保护的相册图像效果\"},{\"position\":\"middle right\",\"description\":\"木门或柜子旁的室内肖像，女性穿着白色水獭 T 恤，齐肩发，温暖的室内光，脸部模糊\"},{\"position\":\"bottom left\",\"description\":\"全身户外街拍，女性站在人行道上比出剪刀手，穿着白色印花 T 恤，浅色长裙，斜挎包，背景中有自行车和树木\"},{\"position\":\"bottom center\",\"description\":\"女性向前倾或蹲下的低角度室内抓拍，可见白色 T 恤，头发散落在模糊的脸部周围，休闲的房间背景\"},{\"position\":\"bottom right\",\"description\":\"强调白色 T 恤上水獭插画的特写裁剪，可见部分模糊的脸部和颈部，温暖的室内光，俏皮的抓拍构图\"}]},\"text\":{\"watermark\":\"{argument name=\\\"watermark text\\\" default=\\\"@yui_ai_model\\\"}\",\"watermark_position\":\"位于左中餐厅照片的左下区域附近\",\"other_text\":\"无标题，无 UI，无可见的应用界面\"},\"camera_and_rendering\":{\"look\":\"真实的手机相册，非摆拍，真实的休闲生活瞬间\",\"lighting\":\"混合日光，温暖室内光，餐厅环境光\",\"quality\":\"写实但不完美的快照，带有运动模糊、轻微噪点、曝光不均，自然的透视畸变\",\"composition\":\"照片紧密重叠并填满整个正方形画布\"},\"customization\":{\"collage_theme\":\"{argument name=\\\"collage theme\\\" default=\\\"休闲抓拍的一天\\\"}\",\"shirt graphic\":\"{argument name=\\\"shirt graphic\\\" default=\\\"可爱的站立水獭\\\"}\"}}","imgs":["https://r2.qqsrc.com/images/originals/18900.jpg"]},{"i":10624,"text":"创作一张正方形构图的动漫集换式卡牌风格插画，主角为 {argument name=\"creature name\" default=\"青眼白龙\"}，这是一条金属白与冰蓝色的巨龙，正从深蓝色的旋转漩涡中猛扑而出。巨龙拥有 1 个硕大的棱角分明的头部，2 只闪烁着蓝宝石光芒的眼睛，张开的咆哮口中长满锋利的三角形牙齿，2 只向后上方延伸的长刃状犄角，2 根从脸颊和下颚处突出的额外尖刺，1 条分节的蛇形脖颈，2 只抬起的前肢配有巨大的弯曲利爪，2 条弯曲的后腿长有爪子，身体和颈部覆盖着多层盔甲状鳞片。强调光泽感十足的铬合金与珍珠质感表面，配以明亮的白色高光、深青色阴影、黑色墨线勾勒以及强烈的镜面反射。生物应以动态的对角线姿势几乎填满整个画面，头部位于左上方附近，利爪伸向观众，尾部和身体卷曲在背景中。背景是一个由发光的蓝色笔触、电光条纹和径向运动模糊构成的充满能量的圆形传送门，营造出速度感与力量感。使用 {argument name=\"color palette\" default=\"冰雪白、铬银色、电光蓝、深海军蓝\"} 配色，高对比度，锐利的动漫线条，奇幻怪物设计，超精细的鳞片与盔甲板，发光高光，精致的数字绘画，无文字，无边框。","imgs":["https://r2.qqsrc.com/images/originals/18901.jpg"]},{"i":10625,"text":"创作一张浅景深写实桌面摄影照片，主体为一个手工制作的层叠剪纸影盒人偶，角色为 {argument name=\"character name\" default=\"一位奇幻炼金术士少女\"}，她站在手工工作室的绿色自愈切割垫上。人偶由多层堆叠的卡纸构成，边缘可见棕色纸板纹理，呈现出 3D 纸模型或纸艺原型测试的效果，具有刻意营造的非完美手工感。她身穿淡薄荷绿长外套，带有层叠裙摆，胸前和腰间交叉着棕色皮带，脚蹬棕色靴子，戴着手套，腰带上挂满了小药水瓶。画面中共有 7 个可见的药水瓶：左手举起 1 个紫色瓶子，左侧腰包上有 1 个小瓶，前腰带上挂着 3 个瓶子，裙子右侧有 2 个瓶子。她的头发颜色为 {argument name=\"hair color\" default=\"淡冰蓝色\"}，长发波浪卷曲且蓬松，被切割成独立的堆叠纸层；她的脸部被一个居中的方形像素化米色模糊遮挡块刻意隐藏。让她呈现出跳跃或漂浮的动态姿势，一只手臂举起拿着瓶子，另一只手向侧面张开，一只靴子抬起，固定在一个带有微型纸草和植物的小型层叠椭圆形展示底座上。人偶周围放置 5 件主要手工工具：左侧有一瓶带有可爱小熊标签的白色挤压式手工胶水，标签文字为 {argument name=\"glue label text\" default=\"Bearly Art Precision Craft Glue\"}，右侧有一把金属尺，右下角有一把银色美工刀，下方是带有白色网格线的绿色切割垫，背景中散落着多个棕色纸板边角料和平面纸样零件。采用温暖的自然室内光，微距镜头视角，真实的纸张纹理，柔和的背景虚化，低饱和度的土色调，以及高细节的写实手工桌面美学。","imgs":["https://r2.qqsrc.com/images/originals/18902.jpg"]},{"i":10626,"text":"{\"type\":\"手工纸雕剪影盒立体透视模型的写实桌面产品照\",\"style\":\"层叠纸艺，激光切割卡纸，3D 纸剧场，温暖的电影感工作室灯光，浅景深，逼真的纸张纤维和切割边缘\",\"main_subject\":{\"description\":\"一个方形黑色剪影盒框架，内含微缩炼金术实验室场景\",\"frame\":\"厚实的哑光炭黑色方形框架，带有深凹的无玻璃开口\",\"central_character\":\"一个由层叠纸张制成的全身奇幻炼金术士冒险家，姿态动感，一手抬起，一手伸出，留着长长的 {argument name=\\\"hair color\\\" default=\\\"白色\\\"} 头发，身穿浅绿色长外套、深绿色长裤，佩戴棕色斜挎皮带、棕色手套、棕色靴子，腰带上挂着小型药水瓶\",\"face\":\"刻意模糊不清，没有可辨认的面部特征\",\"character role\":\"{argument name=\\\"character role\\\" default=\\\"流浪炼金术士\\\"}\"},\"diorama_interior\":{\"setting\":\"古老的木质实验室，堆满了架子、拱形横梁、哥特式窗户、悬挂的灯笼、瓶子、书籍、板条箱和炼金设备\",\"visible_labeled_sign\":{\"count\":1,\"text\":\"{argument name=\\\"sign text\\\" default=\\\"Laboratoire de Saint-Germain Paris, 1768\\\"}\",\"position\":\"右侧墙壁上的羊皮纸牌\"},\"large_props_counted\":{\"hanging_lanterns\":1,\"gothic_windows\":1,\"large_glass_flasks\":3,\"open_books_or_papers\":1,\"wooden_crates\":3,\"small_belt_potion_bottles\":5,\"shelf_bottles_and_jars\":18,\"arched_wood_supports\":3}},\"surrounding_workbench\":{\"surface\":\"木制工艺桌上的绿色自愈切割垫\",\"left_side\":\"一瓶带有 {argument name=\\\"glue label\\\" default=\\\"CRAFT GLUE\\\"} 标签的白色手工胶水，散落的卡纸碎片，镊子\",\"right_side\":\"一把金属尺，一把银色精密美工刀，一个装有画笔和钢笔的玻璃罐，更多纸张边角料，一个木托盘边缘\",\"visible_loose_paper_scraps\":\"框架周围约 34 片不规则的棕褐色、白色、深棕色和鼠尾草绿色卡纸碎片\"},\"camera_and_lighting\":{\"composition\":\"正面四分之三视角，框架居中，略微向下倾斜，背景柔和虚化\",\"lighting\":\"来自左上方的温暖琥珀色工作室灯光，透视模型内部有柔和的阴影，纸张层级细节丰富\",\"lens\":\"写实微距产品摄影，浅景深，4:3 画幅\"},\"color_palette\":\"柔和的鼠尾草绿、棕褐色皮革色、深胡桃木色、炭黑色、羊皮纸米色、灰尘感玻璃蓝绿色\",\"quality\":\"高度精细，逼真的手工制作感，纸张层级间可见深度，无数字插画感，除指定标签外无额外文字\"}","imgs":["https://r2.qqsrc.com/images/originals/18903.jpg"]},{"i":10627,"text":"创作一张垂直全身肖像，呈现为精致的干花拼贴艺术：一位 {argument name=\"subject\" default=\"年轻女性\"} 走在茂密向日葵花田中的狭窄小径上，位于画面中心，双腿交叉，一只手插在磨损的深色牛仔短裤口袋里。她戴着宽檐编织草帽，穿着由层叠蓝色绣球花瓣制成的淡蓝色碎花吊带衫、磨损的牛仔短裤和精致的凉鞋。她深棕色的长发向右飘动，仿佛被柔和的夏日微风吹拂，她的脸部被一个柔和的中性模糊方块遮住，保持身份匿名。整张图像应看起来像是用压制和干燥的植物材料手工制作而成：棕褐色稻草、脆花瓣、种子头、叶子、茎干以及半透明的干花碎片构成了皮肤、衣服、头发和背景。在小径两侧环绕着丰富的金色向日葵，带有巨大的深色种子中心和干燥的赭色花瓣；在她身后，创造一面由层叠蓝色绣球花瓣和成簇白色干花组成的墙。在左上角添加一个风格化的干花太阳，由圆形的压花中心和放射状的稻草茎组成。使用温暖的自然阳光，大地米色和金色调与柔和的绣球花蓝形成对比，具有高度详细的触感纹理、浅景深、精细的植物浮雕、优雅的夏日时尚编辑构图、逼真的比例以及手工压花艺术的美感。","imgs":["https://r2.qqsrc.com/images/originals/18905.jpg"]},{"i":10628,"text":"创作一张白色背景的简洁可爱风动漫 Q 版插画，中心为 {argument name=\"character name\" default=\"一名年轻男性 AI 工程师\"} 蹲姿形象，身穿 {argument name=\"jacket color\" default=\"蓝色西装外套\"}、黑色衬衫、黑色长裤和黑色运动鞋，留着蓬松的黑色短发，佩戴一枚黑色小耳环，脸部从额头到下巴被一个不透明的米色方形审查块完全遮挡。姿势轻松且若有所思：一只手靠近嘴边，另一只手放在膝盖附近，身体低蹲。周围环绕 8 个可爱的 AI 与科技元素：左侧是一个带有白色 GPT 风格结状徽标的绿色圆角方形图块，下方是一个浅蓝色圆角方形聊天机器人图标，左下角是一台屏幕上带有笑脸的打开的笔记本电脑，左上角是一个淡蓝色分子网络图，右上角是一个带有连接节点的深色悬浮分析仪表盘，中右侧是一个紫色圆角方形创意调色板图标，右下角是一个带有蓝色发光眼睛的微型白色圆形机器人吉祥物，机器人附近还有一个小型淡蓝色线框立方体。添加零星的装饰元素：黄色闪光、蓝色动感线条、小型柔和色调圆点和微小圆圈。采用精致的数字艺术风格，柔和的阴影，清晰的线条，光泽感的图标高光，淡蓝色和薰衣草色的点缀，居中构图，无文字，无水印，呈现友好且现代的 AI 吉祥物美学。","imgs":["https://r2.qqsrc.com/images/originals/18906.jpg"]},{"i":10629,"text":"{\"type\":\"编辑类角色概念蒙太奇 / 分镜参考页\",\"style\":\"干净的高调摄影风格，融合城市混凝土跑酷动作镜头，哑光白与浅灰色背景，逼真的全身模特合成，杂志排版，纪录片式运动服目录美学，柔和的漫射光，极简阴影，清晰的剪纸拼贴边缘，柔和的单色调\",\"subject\":{\"role\":\"{argument name=\\\"specialist title\\\" default=\\\"跑酷专家\\\"}\",\"person\":\"年轻女性自由奔跑者，面部刻意用柔和的方形模糊处理，中等身高，运动型苗条身材\",\"age\":\"{argument name=\\\"age\\\" default=\\\"22\\\"}\",\"height\":\"{argument name=\\\"height\\\" default=\\\"165cm\\\"}\",\"outfit\":\"炭灰色超大款套头连帽衫，配抽绳，宽松黑色工装慢跑裤，带侧边绑带，白色运动鞋\",\"hair\":\"{argument name=\\\"hair color and style\\\" default=\\\"中长栗棕色头发，自然散落且略显凌乱\\\"}\"},\"layout\":{\"canvas\":\"方形 1:1 海报，留白充裕，非对称蒙太奇，左侧为严谨的排版，动作姿势沿对角线横跨页面\",\"main_title\":{\"text\":\"{argument name=\\\"headline text\\\" default=\\\"跑酷专家\\\"}\",\"position\":\"左上角\",\"style\":\"粗体压缩大写无衬线字体，深灰色，两行，下方有细横线\"},\"profile_section\":{\"title\":\"个人资料\",\"position\":\"标题下方左上侧\",\"count\":6,\"fields\":[\"年龄：22\",\"身高：165cm\",\"职业：自由奔跑者 / 跑酷运动员\",\"所属：独立\"],\"position\":\"左上角下方\"},\"notes_section\":{\"title\":\"备注\",\"position\":\"左下角\",\"count\":5,\"items\":[\"敏捷且善于观察\",\"思维敏捷\",\"城市环境专家\",\"核心力量强，爆发力足\",\"冷静应对压力\"]},\"pose_montage\":{\"count\":7,\"poses\":[{\"description\":\"正面站立中性全身姿势\",\"position\":\"左上中心\"},{\"description\":\"左侧面站立中性全身姿势\",\"position\":\"中上左侧\"},{\"description\":\"背面站立中性全身姿势\",\"position\":\"中上方\"},{\"description\":\"在混凝土块上低蹲，一膝弯曲，一臂下垂以保持平衡\",\"position\":\"左下角\"},{\"description\":\"中央大型动态爬行 / 着陆姿势，一手靠近地面，一膝收起，身体前倾\",\"position\":\"中心\"},{\"description\":\"右上角翻越墙壁姿势，一手撑在混凝土边缘，双膝侧向抬起，身体悬于墙上\",\"position\":\"右上角\"},{\"description\":\"右侧在狭窄混凝土墙上平衡跑，双臂如翅膀般展开\",\"position\":\"中右侧\"},{\"description\":\"大型裁剪近景跑步或前倾动作姿势，面部模糊，右臂伸出画面外\",\"position\":\"右下角\"}]},\"handwritten_motto\":{\"text\":\"移动 / 适应 / 克服\",\"position\":\"右上角动作姿势附近\",\"style\":\"小型粗糙手写大写笔记，带有短下划线\"},\"key_moves_section\":{\"title\":\"关键动作\",\"position\":\"底部中心\",\"count\":5,\"labels\":[\"精准\",\"速度\",\"流畅\",\"控制\",\"平衡\"],\"visuals\":\"五个黑色小剪影图标，代表跑酷动作，由细垂直分割线隔开\"}},\"composition_notes\":\"创建一个非线性的蒙太奇，打破严格的时间顺序，但保留物理动态和空间方向感。使用混凝土边缘作为极简的环境片段，主要分布在右侧和左下角。所有面部保持模糊/匿名化。避免使用鲜艳颜色；使用炭灰色、黑色、白色和浅混凝土灰色。\"}","imgs":["https://r2.qqsrc.com/images/originals/18907.jpg"]},{"i":10630,"text":"创作一张华丽的竖版奇幻动漫插画，描绘 {argument name=\"goddess name\" default=\"Ame-no-Uzume\"} 在神圣的洞穴神社中起舞，画面呈现如奢华的日本神话塔罗牌风格。构图中心为一名女性舞者，她单脚赤足站在圆形的木制神乐台上，另一膝抬起，一只手高举握着带有红色飘带的金色铃铛神杖，另一只手优雅地向外伸展。她身着灵感源自巫女的华丽分层礼服：飘逸的白色和服袖子、红色内衬、金色花卉刺绣、黑金相间的华丽腰饰、编织绳结、流苏、脚链和珠宝；她长长的黑发在巨大的花卉金饰神冠下围绕身体戏剧性地飘动。她的面部应柔化处理或保持无五官细节。背景是耀眼的暖金色洞口，上方挂着粗壮的注连绳和 6 条垂下的纸垂。舞台周围环绕着 6 名背景侍从或神明，左右各 3 名，半隐于阴影中，面部模糊或柔化，双手举起或持乐器，仿佛在崇拜并庆祝这场舞蹈。添加旋转的花瓣、闪烁的星光、薄雾、丝带以及充满魔法倒影的深靛紫色洞穴。使用极其精致的金色花丝边框，四角饰有大型花卉装饰、悬垂的流苏、铃铛和宝石，顶部和底部中心饰有圆形菊花纹章。光影效果戏剧化且神圣，具有强烈的背光、暖金色高光、冷蓝紫色阴影、光泽面料、复杂的装饰细节、动态感、高奇幻风格、高细节动漫绘画、电影感竖版海报，无任何可读文字。","imgs":["https://r2.qqsrc.com/images/originals/18908.jpg"]},{"i":10631,"text":"{\"type\":\"可爱动漫 VTuber 徽章 Logo 贴纸\",\"style\":\"高质感日本抽卡游戏主视觉风格，光泽亚克力挂件质感，加粗白色贴纸轮廓，粉彩霓虹配色，清晰的矢量风格排版与细腻的动漫渲染相结合，带有闪光、爪印、爱心、星星及电子宠物元素\",\"canvas\":\"1:1 正方形构图，黑色背景，居中圆形徽章，带有粉色、蓝色、白色和淡紫色的多层轮廓\",\"main subject\":{\"count\":1,\"description\":\"可爱的动漫猫狼少女吉祥物，从 Logo 文字后方探出，上半身肖像，开心的张嘴微笑，露出小虎牙，脸颊泛红，明亮的大绿眼睛，夸张的睫毛\",\"hair\":\"{argument name=\\\"hair color\\\" default=\\\"深宝蓝色头发，带有白色前刘海和亮青色侧边挑染\\\"}，右肩垂下一条厚实的长侧辫，蓬松的层次感刘海\",\"ears\":\"两只竖立的大型动物耳朵，蓝色外层绒毛，白色内耳簇毛，深色耳尖\",\"pose\":\"右手在脸旁比出剪刀手，肩膀放松，面向观众\",\"outfit\":\"浅蓝色罗纹上衣，黑色颈圈配小搭扣，滑落肩头的超大号黑色夹克，带有白色毛绒领边，配有小带子和青色装饰，手腕上有手链和悬挂的吊牌\"},\"central typography\":{\"count\":2,\"items\":[{\"text\":\"{argument name=\\\"main Japanese logo text\\\" default=\\\"安喰美蓮\\\"}\",\"position\":\"底部中央的大型前景\",\"appearance\":\"粗体圆润日文字符，光泽感 3D 气泡字体，蓝白配色字母，中间包含一个大粉色字符，带有厚重的白紫色轮廓，填充爪印装饰及糖果般的反光高光\"},{\"text\":\"{argument name=\\\"romanized name text\\\" default=\\\"AZAMI MIREN\\\"}\",\"position\":\"日文 Logo 下方的粉色丝带横幅\",\"appearance\":\"弯曲粉色丝带上的白色间距大写字母，带有小型星星分隔符\"}]},\"background badge\":{\"count\":1,\"description\":\"角色后方的大型圆形粉彩徽章，以淡粉色为主，带有蓝色渐变、半调网点纹理、网格面板、闪粉、星星及贴纸般的层叠边框\"},\"surrounding decorative elements\":{\"count\":14,\"items\":[\"左上角带有爱心图标和网格线的浏览器窗口卡片\",\"右上角的青色爪印对话气泡\",\"右侧的蓝色狼头剪影贴纸\",\"右下角的大型青色轮廓星星\",\"左下角的粉色爱心对话气泡\",\"左下和右下边缘的两个超大号粉色别针\",\"底部悬挂的黑色链条\",\"底部居中的心形挂锁吊坠\",\"右下角的白色游戏手柄，带有粉色加号键和青色按钮\",\"左袖上悬挂的小型姓名吊牌，写着 MIREN\",\"Logo 周围多个粉色和蓝色爪印贴纸\",\"圆形徽章周围的小型星星和闪光贴纸\",\"底部附近的粉色十字和蓝色 X 装饰符号\",\"侧边边缘附近的音符图标\"]},\"color palette\":\"{argument name=\\\"color palette\\\" default=\\\"粉彩粉色、电光蓝、青色、淡紫色、白色及光泽感藏青色点缀\\\"}\",\"rendering instructions\":\"使图像呈现出高级 VTuber 名称 Logo、亚克力钥匙扣贴纸或直播徽章的质感；强调干净的线条、明亮的高光、立体的排版、可爱活力的表情、密集且平衡的装饰，角色身上不要佩戴项链，不要追求写实风格\"}","imgs":["https://r2.qqsrc.com/images/originals/18909.jpg"]},{"i":10632,"text":"创作一张逼真的桌面产品照片，展示一个手工层叠纸艺阴影盒手办：一个由堆叠切割卡纸制成的动态奇幻炼金术士女孩，站在一个小巧的椭圆形层叠纸板底座上。该角色拥有 {argument name=\"hair color\" default=\"淡冰蓝色\"} 的长波浪卷发，由独立的卷曲纸层构成；身穿薄荷绿长外套，配有棕褐色仿皮纸质绑带、腰带、搭扣、手套和棕色靴子，姿态处于迈步中，仿佛正在跳舞或举杯。她的面部被刻意用柔和的方形模糊处理。左手高举 1 个紫色药水瓶，腰带上精确携带 6 个白色、蓝色和琥珀色调的小药水瓶，每个瓶子均由微小的层叠纸片拼搭而成。底座包含小纸草丛和岩石。将手办放置在带有白色切割痕迹的绿色自愈切割垫上，背景为温暖的浅景深手工工作区。在手办周围放置 3 个显眼的工具或用品：左侧是一个带有牛皮纸标签的白色胶水瓶，标签上写着 {argument name=\"glue label text\" default=\"Beardy Art Premium Craft Glue\"}，右侧是一把银色金属尺，右下角是一把银色精密美工刀。在垫子上散落棕色牛皮纸边角料，背景中模糊显示着堆叠的纸板。使用温暖的工作室灯光、微距摄影，呈现高度细腻的纸张纤维、清晰可见的层叠边缘、柔和的阴影、逼真的手工微缩质感，以及受 {argument name=\"series title\" default=\"Toxic Party\"} 启发的奇幻收藏艺术风格。","imgs":["https://r2.qqsrc.com/images/originals/18910.jpg"]},{"i":10633,"text":"创作一张照片级逼真的桌面产品摄影图，展示一个置于深色方形黑框内的手工分层纸艺立体剪影盒，画面中心是一位来自 {argument name=\"series title\" default=\"Toxic Party\"} 的奇幻炼金术士女孩，正站在古老的实验室中。角色拥有 {argument name=\"hair color\" default=\"长长的飘逸白发\"}，面部部分模糊或柔和遮挡，身穿浅绿色长款开叉大衣、深绿色打底裤、棕色皮靴，配有交叉胸带、腰带包，腰间系着 7 个小药水瓶。让她摆出动态姿势，一只手臂抬起做出问候或施法的手势，另一只手臂向侧面伸展。整个内部结构由分层剪纸和硬纸板构建，呈现出明显的堆叠深度：拱形架子、哥特式窗户、木梁、石砖地面和温暖的灯笼光。在立体剪影盒中包含 24 个实验室器皿和瓶子：左侧上层架子 7 个，左侧下层架子及桌上 6 个，后方中间架子 4 个，右侧架子 3 个，地面大瓶 2 个，前景家具上附带 2 个。在盒内添加 5 个主要的前景道具：一本打开的绘有炼金术图表的素描本、一张矮工作台、一个小板条箱、一个带有橙色火焰的熔炉或火盆，以及一个大型圆底烧瓶。在右侧墙壁上，添加一块羊皮纸标志，上面写着 {argument name=\"sign text\" default=\"Laboratoire de Saint-Germain Paris, 1768\"}。在框架式立体剪影盒周围布置一个真实的手工工作台：绿色切割垫、散落的棕褐色、棕色、鼠尾草绿和白色纸屑、一把金属尺、精密美工刀、镊子、一瓶贴有 {argument name=\"glue label\" default=\"CRAFT GLUE\"} 标签的工艺胶水、一个装有画笔和铅笔的罐子以及一个纸板箱。使用浅景深、温暖的摄影棚灯光、逼真的纸张纤维质感、每层剪纸之间微妙的阴影，营造出舒适的手工立体剪影盒美学。","imgs":["https://r2.qqsrc.com/images/originals/18911.jpg"]},{"i":10634,"text":"创作一张写实风格的广角室内摄影作品，展示黄金周期间昏暗的日本柏青哥店过道。画面中需精确呈现 {argument name=\"number of slot machines\" default=\"7\"} 台并排靠墙摆放的海盗主题柏青哥机，以及前方 {argument name=\"number of chairs\" default=\"7\"} 把空置的黑色乙烯基转椅。每台机器均配有亮面黑色外壳、发光的红色 LED 面板，以及带有 BAR、樱桃、铃铛和橘子符号的照明转轮窗口；下部显示屏上印有 {argument name=\"machine title text\" default=\"King of Carib\"} 字样的华丽海盗船图案；顶部显示屏显示红色的“777”及“Big Chance”字样。场景应营造出安静且略带神秘的氛围，画面中无人，充满深邃的阴影，伴有红色和琥珀色的赌场灯光，抛光的深色木地板上映出倒影，机器上方悬挂着隐约可见的日本警示标识。采用写实的纪实快照风格，平视视角，强对比度，低调的氛围曝光，清晰的机器细节，镜头在过道处呈现轻微的透视拉伸，采用 16:9 横向构图。","imgs":["https://r2.qqsrc.com/images/originals/18912.jpg"]},{"i":10635,"text":"创作一幅电影级动漫风格插画，描绘一名 {argument name=\"subject\" default=\"疲惫的高中足球运动员\"} 在训练后直接从学校户外喷泉喝水的场景。画面中需精确呈现一个长方形混凝土喷泉上的 2 个铬合金水龙头：上方水龙头位于嘴部高度，正喷出一股清澈的水流进入他张开的嘴里；下方水龙头安装在正面，正滴着水。在左侧潮湿的混凝土台面上放置 1 个深蓝色运动水壶。男孩侧身弯腰，浑身被汗水和水珠浸透，留着凌乱湿润的 {argument name=\"hair color\" default=\"深棕色\"} 头发，脸颊泛红，表情疲惫而清爽。他身穿带有蓝白侧条纹的黑色短袖运动足球服，搭配黑色短裤，脖子上挂着一条白色毛巾，上面印有日文 {argument name=\"towel text\" default=\"青葉高校 サッカー部\"}。场景设置在学校运动场和社团大楼旁，时间为 {argument name=\"time of day\" default=\"黄金时刻的日落\"}，带有温暖的橙色背光、长长的阴影、远处的球网和电线杆，墙上挂着写有“部室”的小牌子，混凝土上有水花溅落，水珠闪烁着光芒，浅景深，精细的手绘动漫渲染，写实的水龙头构造，戏剧性的轮廓光，竖构图，画面中无其他人物。","imgs":["https://r2.qqsrc.com/images/originals/18913.jpg"]},{"i":10636,"text":"{\"type\":\"奢华高尔夫时尚杂志封面\",\"format\":\"竖版编辑封面，照片级真实感数字艺术，光面杂志设计\",\"title_text\":\"{argument name=\\\"magazine title\\\" default=\\\"GSM\\\"}\",\"scene\":{\"setting\":\"阳光明媚的高尔夫球道，背景为柔和的绿色虚化效果，温暖的春日晨光，浅景深\",\"main_subject\":\"优雅的成年女性高尔夫时尚模特，站在高尔夫球车和球包旁，姿态自信放松，一只戴手套的手放在腰间附近，另一只手臂自然下垂\",\"face_treatment\":\"面部被一个居中的暖棕色不透明矩形遮挡块刻意遮盖，遮住了五官\",\"wardrobe\":{\"style\":\"2026 年精致春夏高尔夫时尚，纯净的白色至象牙白单色造型\",\"pieces_count\":5,\"pieces\":[\"象牙白色无袖罗纹高领针织高尔夫上衣\",\"白色高腰高尔夫短裙，前片带褶皱\",\"白色腰带，配银色扣环\",\"右手佩戴白色高尔夫手套\",\"胸前带有精致刺绣标志\"]},\"hair\":\"{argument name=\\\"hair color\\\" default=\\\"栗棕色长卷发\\\"}\",\"props\":{\"count\":3,\"items\":[\"右前方的黑米色奢华高尔夫球包\",\"包内可见多支金属杆头的闪亮高尔夫球杆\",\"右上角的白色高尔夫球车顶棚及支撑架局部\"]}},\"layout\":{\"composition\":\"模特位于中心和右侧，高尔夫球包位于右前方，编辑文本主要左对齐，左上角有大型刊头，右上角有圆形专题徽章\",\"cover_text_blocks_count\":11,\"cover_text_blocks\":[{\"position\":\"刊头上方左侧\",\"text\":\"GOLF STYLE MAGAZINE\",\"style\":\"小型大写无衬线字体，字间距较宽\"},{\"position\":\"左上角刊头\",\"text\":\"{argument name=\\\"masthead text\\\" default=\\\"GSM\\\"}\",\"style\":\"超大优雅白色衬线字体\"},{\"position\":\"刊头下方\",\"text\":\"2026 春夏\\n高尔夫时尚特刊\",\"style\":\"小型白色无衬线字体\"},{\"position\":\"左侧中上部\",\"text\":\"2026\\nGOLF\\nFASHION\\nTREND\",\"style\":\"加粗堆叠式白色大写无衬线字体\"},{\"position\":\"趋势标题下方\",\"text\":\"次のシーズンを制するのは、\\n洗練された“機能美”。\",\"style\":\"小型白色日文文本\"},{\"position\":\"左侧中部专题标签\",\"text\":\"Special Feature\",\"style\":\"小型白色衬线字体，带细横线\"},{\"position\":\"左侧中部主专题\",\"text\":\"{argument name=\\\"main feature text\\\" default=\\\"私らしく、\\nもっと遠くへ。\\\"}\",\"style\":\"大型白色日文毛笔风格衬线字体\"},{\"position\":\"主专题下方\",\"text\":\"ゴルフがくれる自由と美しさ。\\n新しい季節の、私のスタイル。\",\"style\":\"小型白色日文正文\"},{\"position\":\"左侧中下部\",\"text\":\"STYLE\\nMATCH\\n场景别推荐\\n搭配\",\"style\":\"加粗白色无衬线标题，配小型日文副标题\"},{\"position\":\"左下角\",\"text\":\"2026\\nNEW GEAR\\n最新球杆与装备\\n深度评测\",\"style\":\"加粗白色无衬线标题，配小型日文副标题\"},{\"position\":\"左下角制作人员名单\",\"text\":\"COVER MODEL\\n@Image 1\\n\\nPhotographed by\\nGSM Editorial Team\",\"style\":\"微型白色制作人员名单\"}],\"badge\":{\"position\":\"右上角\",\"shape\":\"细白色轮廓圆圈\",\"text\":\"Exclusive\\nInterview\\n\\n顶尖职业选手谈\\n『胜出的\\n风格』\",\"style\":\"圆圈内白色衬线字体与日文无衬线字体\"}},\"visual_style\":{\"photography\":\"高端时尚编辑真实感，电影级自然光，高级杂志封面，主体清晰，高尔夫球场背景虚化\",\"color_palette\":\"白色、象牙白、米色、柔和绿、黑色点缀、暖色高光\",\"typography\":\"优雅衬线刊头、加粗现代无衬线封面标题、小型日文编辑正文的混合排版\",\"mood\":\"精致、向往感、运动风、女性化、干练\"},\"quality\":\"超高细节，真实的织物纹理，光亮的高尔夫球杆，专业的封面排版，印刷级构图\"}","imgs":["https://r2.qqsrc.com/images/originals/18914.jpg"]},{"i":10637,"text":"{\"type\":\"照片级真实感奢华日系高尔夫时尚杂志封面\",\"format\":\"竖版印刷封面，3:4 比例\",\"subject\":{\"description\":\"一位年轻女性高尔夫模特站在阳光明媚的高尔夫球道上，头部至大腿中部的四分之三身位特写，姿态放松自信，右手垂直握着一支高尔夫球杆，戴着一只白色高尔夫手套\",\"face\":\"面部被一个位于中心位置的柔边深棕色矩形隐私遮挡块刻意遮盖\",\"hair\":\"长波浪深棕色头发，侧分，有光泽，垂落在肩膀上\",\"outfit\":{\"count\":4,\"items\":[\"奶油白色罗纹短袖拉链 Polo 衫，带衣领\",\"浅米白色高腰高尔夫短裙，带百褶侧边\",\"白色腰带，配方形金色扣\",\"白色高尔夫手套\"],\"dominant color\":\"{argument name=\\\"outfit color\\\" default=\\\"柔白色和浅米色\\\"}\"}},\"setting\":{\"location\":\"高尔夫球道\",\"background\":\"模糊的绿色草地，远处的树木，明亮的春日阳光，浅景深\",\"mood\":\"优雅、清新、运动、精致、令人向往\"},\"typography\":{\"style\":\"高端时尚杂志排版，大型精致衬线字体刊头，金米色和黑色日文编辑文本，干净的白色叠加文本，宽敞的间距\",\"masthead\":\"{argument name=\\\"magazine title\\\" default=\\\"GOLF\\\"}\",\"right masthead text\":\"STYLE JAPAN\"},\"layout\":{\"top\":{\"count\":3,\"elements\":[\"左上角小字：2026 SPRING & SUMMER [ゴルフスタイルジャパン]\",\"上半部分巨大的金色衬线字体刊头：{argument name=\\\"magazine title\\\" default=\\\"GOLF\\\"}\",\"右上角标语：ゴルフをもっと、スタイリッシュに。\"]},\"right side\":{\"count\":3,\"elements\":[\"大型堆叠标题：STYLE JAPAN\",\"期刊块：{argument name=\\\"season and issue\\\" default=\\\"2026 SPRING & SUMMER VOL.58\\\"}\",\"小型专题徽章和文字：Course Snap / 人気インフルエンサーのリアルコーディネート in 名門コース\"]},\"left side feature column\":{\"count\":4,\"elements\":[\"专题徽章及主日文标题：{argument name=\\\"main Japanese headline\\\" default=\\\"春のゴルフは、私らしく。\\\"} 以及副标题：軽やかに、美しく、心地よく。新しい季節のゴルフスタイル。\",\"季节趋势徽章及文字：最旬カラーで魅せる！2026 春夏のゴルフウェアトレンド\",\"时尚与功能徽章及文字：おしゃれも快適さもあきらめない。高機能ウェアコレクション\",\"品牌精选徽章及文字：注目ブランドの新作アイテムをチェック\"]},\"lower right\":{\"count\":2,\"elements\":[\"大型白色英文口号：{argument name=\\\"English slogan\\\" default=\\\"New Season, New Style.\\\"}\",\"下方较小的日文行：新しい季節、新しい私。\"]}},\"visual details\":{\"lighting\":\"温暖的自然日光，头发和肩膀上有微妙的轮廓光\",\"camera\":\"时尚编辑摄影，85mm 镜头感，浅景深，主体清晰，高尔夫球场背景柔和模糊\",\"color palette\":\"奶油色、米色、浅金色、柔绿色、白色\",\"composition\":\"模特略微偏右居中，刊头位于头部和肩膀后方，编辑文本围绕身体排列且不遮挡服装，高端日系高尔夫生活方式封面\",\"quality\":\"超写实，高分辨率印刷设计，精致杂志封面，无额外人物，除设计好的封面排版外无其他 Logo\"}}","imgs":["https://r2.qqsrc.com/images/originals/18915.jpg"]},{"i":10638,"text":"{\"type\":\"日本女性高尔夫球装时尚杂志编辑页面，照片级逼真奢华数字艺术\",\"format\":\"单页垂直杂志页面，全出血编辑排版，柔和自然日光，优雅的奶油色与鼠尾草灰配色\",\"main_subject\":{\"description\":\"一位时尚的成年女性高尔夫球手，站在室内高窗旁，窗外是朦胧的城市天际线，留着长波浪棕色卷发，面部柔和虚化，姿态自信放松\",\"outfit\":\"{argument name=\\\"golf outfit\\\" default=\\\"灰色提花拉链前襟无袖迷你高尔夫连衣裙，带有精致的字母组合纹理\\\"}\",\"accessories\":\"白色宽腰带配圆形扣，白色高尔夫手套，白色短袜，白色厚底高尔夫球鞋，在嵌入式全身图中手持高尔夫球杆\",\"mood\":\"精致、女性化、现代、运动、高端\"},\"layout\":{\"page_count\":1,\"sections_count\":5,\"sections\":[{\"title\":\"●●特集 进化中的女性高尔夫球手 2026 最新风格\",\"position\":\"top left\",\"role\":\"小型日本专题标题\"},{\"title\":\"兼具优雅与功能性的精致高尔夫风格\",\"position\":\"left side vertical text\",\"role\":\"垂直日文编辑标语\"},{\"title\":\"美丽，做自己。让高尔夫更有趣的服装\",\"position\":\"upper right above masthead\",\"role\":\"小型日文副标题\"},{\"title\":\"Elegance on the Green\",\"position\":\"upper right center\",\"role\":\"大型深绿色斜体衬线标题\",\"headline\":\"{argument name=\\\"headline text\\\" default=\\\"Elegance on the Green\\\"}\"},{\"title\":\"Pick Up Item\",\"position\":\"bottom left\",\"role\":\"产品价格列表\",\"item_count\":5,\"items\":[\"压花立领连衣裙 ¥18,700\",\"白色腰带 ¥6,600\",\"Logo 手套 ¥3,960\",\"无钉球鞋 ¥15,400\",\"模特穿着的灰色字母组合高尔夫连衣裙\"]}],\"inset_panels_count\":2,\"inset_panels\":[{\"label\":\"Style 01\",\"position\":\"right middle\",\"description\":\"带白色边框的全身嵌入图，展示同一位高尔夫球手站在窗边手持高尔夫球杆，完整展示服装\"},{\"label\":\"POINT\",\"position\":\"bottom right\",\"description\":\"带有 3 个已勾选造型说明的小型清单框\",\"checklist_count\":3,\"checklist\":[\"展现优美腰线的剪裁\",\"弹力面料支持舒适挥杆\",\"简约配色营造优雅印象\"]}],\"footer\":{\"position\":\"bottom left\",\"text\":\"23 Golf Style Spring & Summer 2026\"},\"year\":\"{argument name=\\\"year\\\" default=\\\"2026\\\"}\"},\"typography\":{\"headline_style\":\"深森林绿色的优雅大号斜体衬线字体\",\"body_style\":\"黑色与灰色的小型日文杂志正文，干净简约的编辑排版\",\"number_badge\":\"包含 Style 01 的细圆形轮廓\"},\"environment\":{\"setting\":\"落地窗旁的现代高层室内\",\"background\":\"模糊的明亮城市天际线，温暖的米色窗框，干净的极简主义建筑\",\"lighting\":\"来自窗户的柔和晨光，织物纹理上的柔和高光\"},\"camera_and_composition\":{\"orientation\":\"肖像 3:4 杂志封面/页面\",\"main_crop\":\"模特从头部到大腿上部的四分之三裁剪，占据左半部分\",\"secondary_crop\":\"右侧的全身嵌入图\",\"depth_of_field\":\"浅景深，服装纹理清晰，城市背景模糊\"},\"style_keywords\":\"日本高尔夫时尚杂志, 2026 趋势编辑, 优雅女性运动装, 高端目录设计, 真实时尚摄影, 干净排版, 精致春夏高尔夫风格\",\"customizable_brand_initial\":\"{argument name=\\\"brand initial\\\" default=\\\"G\\\"}\"}","imgs":["https://r2.qqsrc.com/images/originals/18916.jpg"]},{"i":10639,"text":"创作一幅精致的动漫风格旅行插画，背景设定在 {argument name=\"location\" default=\"北海道阿寒摩周国立公园阿寒湖\"} 的晴朗明媚之日。画面前景中需精确呈现 4 个人物：中间是一位年轻的女性导游，拥有逼真的松鼠耳朵、一头飘逸的 {argument name=\"hair color\" default=\"暖棕色\"} 长发、装饰性发夹和垂坠耳环，身穿一套华丽的深蓝色配米色阿伊努风格导游制服，带有刺绣几何花边、流苏、腰带绳和层叠袖口；另外 3 名游客正在聆听，包括左侧戴着棕色棒球帽的年轻男子、中心前景处坐着或位置较低的戴米色渔夫帽的女性，以及右侧扎着马尾辫、手持宣传册的女性。导游自信地站在木制观景台标志旁，手中拿着一本蓝色的旅行宣传册，标题为 {argument name=\"brochure title\" default=\"阿寒湖导游地图\"}，同时伸出一只手臂指向湖泊和群山，仿佛正在介绍风景。画面中包含一个木制标志，上面用日文和英文写着 {argument name=\"sign text\" default=\"阿寒摩周国立公園 / Akan-Mashu National Park / 阿寒湖 / Lake Akan\"}。背景描绘了湛蓝的湖泊、观光船、翠绿的森林山脉、远处的湖岸线、护栏以及深蓝色的天空和丝缕白云。添加精确的 18 个半透明虹彩肥皂泡：1 个巨大的松鼠尾巴形状的泡泡在导游右后方卷曲，2 个巨大的圆形泡泡高悬在天空中，5 个中型泡泡环绕在她的头部和上半身周围，10 个微小的泡泡散落在她的头发、袖子和腰部周围。运用肥皂泡上的发光彩虹反射、清晰的线条、电影级的构图、细腻的织物装饰、柔和的阳光、高分辨率的动漫写实风格、欢快的旅游海报氛围以及奇幻魔法导游的概念。","imgs":["https://r2.qqsrc.com/images/originals/18917.jpg"]}];